#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct RuntimeDispatchTargetResolution {
    /// Stable TeamFlow node identity used by executable/persisted state.
    pub(crate) node_id: String,
    pub(crate) dispatch_target: String,
    pub(crate) lane_id: Option<String>,
}

#[cfg(test)]
fn dispatch_target_resolution_from_lane(
    lane_id: &str,
    lane: &serde_json::Value,
) -> Option<RuntimeDispatchTargetResolution> {
    let lane_id = lane_id.trim();
    if lane_id.is_empty() {
        return None;
    }
    let dispatch_target = json_string(lane.get("dispatch_target"))
        .or_else(|| json_string(lane.get("target")))
        .unwrap_or_else(|| canonical_dispatch_target_name(lane_id));
    let dispatch_target = dispatch_target.trim();
    if dispatch_target.is_empty() {
        return None;
    }
    Some(RuntimeDispatchTargetResolution {
        node_id: lane
            .get("node_id")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(lane_id)
            .to_string(),
        dispatch_target: dispatch_target.to_string(),
        lane_id: (lane_id != dispatch_target).then(|| lane_id.to_string()),
    })
}

#[cfg(test)]
pub(crate) fn diagnostic_resolve_runtime_dispatch_target(
    execution_plan: &serde_json::Value,
    lane_or_target: &str,
) -> Option<RuntimeDispatchTargetResolution> {
    let candidate = lane_or_target.trim();
    if candidate.is_empty() {
        return None;
    }
    let canonical_candidate = canonical_dispatch_target_name(candidate);
    let lane_catalog =
        execution_plan["development_flow"]["dispatch_contract"]["lane_catalog"].as_object();
    for lookup in [candidate, canonical_candidate.as_str()] {
        if let Some(resolution) = lane_catalog
            .and_then(|catalog| catalog.get(lookup))
            .and_then(|lane| dispatch_target_resolution_from_lane(lookup, lane))
        {
            return Some(resolution);
        }
    }
    if let Some(catalog) = lane_catalog {
        for (lane_id, lane) in catalog {
            let configured_target = json_string(lane.get("dispatch_target"))
                .or_else(|| json_string(lane.get("target")))
                .map(|value| canonical_dispatch_target_name(&value));
            let configured_alias = json_string(lane.get("dispatch_alias"));
            if configured_target.as_deref() == Some(canonical_candidate.as_str())
                || configured_alias.as_deref() == Some(candidate)
            {
                return dispatch_target_resolution_from_lane(lane_id, lane);
            }
        }
    }
    None
}

pub(crate) fn normalized_dispatch_target_token(value: &str) -> String {
    value.trim().to_string()
}

#[cfg(test)]
pub(crate) fn rework_alias_base_dispatch_target(value: &str) -> Option<String> {
    normalized_dispatch_target_token(value)
        .strip_suffix("_rework")
        .map(str::to_string)
        .filter(|base| !base.trim().is_empty())
}

pub(crate) fn backend_policy_dispatch_target_for_resolution(
    resolution: &RuntimeDispatchTargetResolution,
) -> &str {
    resolution
        .lane_id
        .as_deref()
        .unwrap_or(resolution.dispatch_target.as_str())
}

pub(crate) fn policy_dispatch_target_for_admissibility(
    _execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> String {
    dispatch_target.trim().to_string()
}

pub(crate) fn first_runtime_dispatch_target_after_dev_pack(
    role_selection: &RuntimeConsumptionLaneSelection,
) -> Result<RuntimeDispatchTargetResolution, String> {
    let authority = require_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;

    let selected_node_id = validated_selected_flow_node_ref(role_selection)?
        .ok_or_else(|| "team_flow_authority_selected_node_id_missing".to_string())?;
    let selected_node = authority
        .resolve_target(None, &selected_node_id)
        .map_err(|blocker| blocker.to_string())?;
    if !selected_node.included {
        return Err(format!(
            "team_flow_authority_selected_node_id_excluded:{selected_node_id}"
        ));
    }

    Ok(RuntimeDispatchTargetResolution {
        node_id: selected_node.node_id,
        dispatch_target: selected_node.dispatch_target.clone(),
        lane_id: (selected_node.lane_id != selected_node.dispatch_target)
            .then_some(selected_node.lane_id),
    })
}

/// Return the first persisted TeamFlow selection carried by a runtime lane selection.
///
/// This accessor is diagnostic-only. Executable consumers must use
/// `validated_selected_flow_ref` so conflicting persisted identities fail closed.
pub(crate) fn selected_flow_ref(role_selection: &RuntimeConsumptionLaneSelection) -> Option<&str> {
    [
        role_selection.execution_plan["team_flow_authority_selected_flow_id"].as_str(),
        role_selection.execution_plan["development_flow"]["dispatch_contract"]["selected_flow_set"]
            .as_str(),
        role_selection.execution_plan["selected_flow_contract"]["flow_id"].as_str(),
        role_selection.execution_plan["team_flow_authority"]["selected_flow_id"].as_str(),
    ]
    .into_iter()
    .flatten()
    .map(str::trim)
    .find(|value| !value.is_empty())
    .or_else(|| {
        role_selection.matched_terms.iter().find_map(|term| {
            term.strip_prefix("dev_team_flow_id:")
                .map(str::trim)
                .filter(|value| !value.is_empty())
        })
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum SelectedFlowIdentityMode {
    Fresh,
    Persisted,
    Replay,
}

/// Resolve one executable TeamFlow identity from all persisted selection evidence.
///
/// Fresh selections may have no explicit identity and therefore select the configured
/// default. Persisted and replayed selections must keep every available identity,
/// including the current TaskFlow binding, equal.
pub(crate) fn validated_selected_flow_ref(
    role_selection: &RuntimeConsumptionLaneSelection,
    task_flow_ref: Option<&str>,
    mode: SelectedFlowIdentityMode,
) -> Result<Option<String>, TeamFlowResolutionBlocker> {
    let mut evidence = Vec::new();
    let mut push = |source: &'static str, value: Option<&str>| {
        if let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) {
            evidence.push((source, value.to_string()));
        }
    };
    push(
        "execution_plan",
        role_selection.execution_plan["team_flow_authority_selected_flow_id"].as_str(),
    );
    push(
        "dispatch_contract",
        role_selection.execution_plan["development_flow"]["dispatch_contract"]["selected_flow_set"]
            .as_str(),
    );
    push(
        "selected_flow_contract",
        role_selection.execution_plan["selected_flow_contract"]["flow_id"].as_str(),
    );
    push(
        "team_flow_authority",
        role_selection.execution_plan["team_flow_authority"]["selected_flow_id"].as_str(),
    );
    for term in &role_selection.matched_terms {
        push("matched_term", term.strip_prefix("dev_team_flow_id:"));
    }
    push("task_binding", task_flow_ref);

    let identities = evidence
        .iter()
        .map(|(_, value)| value.as_str())
        .collect::<BTreeSet<_>>();
    if identities.len() > 1 {
        return Err(TeamFlowResolutionBlocker {
            code: "team_flow_selected_flow_identity_conflict".to_string(),
            requested: "persisted TeamFlow identities must agree".to_string(),
            candidates: evidence
                .into_iter()
                .map(|(source, value)| format!("{source}={value}"))
                .collect(),
        });
    }
    let selected = identities.into_iter().next().map(str::to_string);
    if selected.is_none() && mode != SelectedFlowIdentityMode::Fresh {
        return Err(TeamFlowResolutionBlocker {
            code: "team_flow_selected_flow_identity_missing".to_string(),
            requested: format!("{mode:?} TeamFlow identity is required"),
            candidates: Vec::new(),
        });
    }
    Ok(selected)
}

/// Compile a fresh-or-explicit validated TeamFlow selection.
pub(crate) fn require_team_flow_authority_for_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
) -> Result<TeamFlowExecutionAuthority, TeamFlowResolutionBlocker> {
    let flow_ref =
        validated_selected_flow_ref(role_selection, None, SelectedFlowIdentityMode::Fresh)?;
    require_team_flow_execution_authority(
        &role_selection.compiled_bundle,
        flow_ref.as_deref(),
        None,
    )
}

pub(crate) fn require_persisted_team_flow_authority_for_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
) -> Result<TeamFlowExecutionAuthority, TeamFlowResolutionBlocker> {
    let flow_ref =
        validated_selected_flow_ref(role_selection, None, SelectedFlowIdentityMode::Persisted)?;
    require_team_flow_execution_authority(
        &role_selection.compiled_bundle,
        flow_ref.as_deref(),
        None,
    )
}

pub(crate) fn resolve_team_flow_target_for_selection(
    authority: &TeamFlowExecutionAuthority,
    execution_plan: Option<&Value>,
    target: &str,
) -> Result<crate::team_flow_authority_adapter::TeamFlowNodeResolution, TeamFlowResolutionBlocker> {
    let blocker = match authority.resolve_target(execution_plan, target) {
        Ok(node) => return Ok(node),
        Err(blocker) => blocker,
    };
    if matches!(
        target.trim(),
        "closure" | "closure_lane" | "terminal_closure"
    ) {
        let terminal_nodes = authority
            .ordered_nodes()
            .filter(|projection| projection.node.terminal)
            .collect::<Vec<_>>();
        if terminal_nodes.len() == 1 {
            return authority.resolve_target(execution_plan, &terminal_nodes[0].node.node_id);
        }
    }
    let canonical_target = canonical_dispatch_target_name(match target.trim() {
        "pm" | "product_manager" | "product-management" => "business_analyst",
        "implementer" | "writer" | "developer" => "development_implementer",
        "tester" | "verification" | "verifier" | "review_ensemble"
        | "verification_ensemble" => "development_verifier",
        "coach" | "review" | "coach_validator" => "development_coach",
        "architecture" | "architect" | "designer" | "execution_preparation" => {
            "development_execution_preparation"
        },
        "closure" | "closure_lane" | "terminal_closure" => "development_release_closure",
        // Legacy packet receipts use the task-class label while the persisted
        // authority exposes the canonical dispatch alias.
        "specification" => "development_specification",
        other => other,
    });
    if canonical_target.is_empty() {
        return Err(blocker);
    }
    let matches = authority
        .ordered_nodes()
        .filter(|projection| {
            [
                projection.node.node_id.as_str(),
                projection.dispatch_target.as_str(),
                projection.dispatch_alias.as_str(),
                projection.node.runtime_role.as_str(),
                projection.node.task_class.as_str(),
            ]
            .into_iter()
            .filter(|candidate| !candidate.trim().is_empty())
            .any(|candidate| {
                let candidate = canonical_dispatch_target_name(candidate);
                candidate == canonical_target
                    || (canonical_target == "development_specification"
                        && candidate == "specification")
            })
        })
        .collect::<Vec<_>>();
    if matches.len() != 1 {
        return Err(blocker);
    }
    authority.resolve_target(execution_plan, &matches[0].node.node_id)
}

/// Marker persisted on legacy initial plans that have no selected node id.
pub(crate) const TEAM_FLOW_SELECTED_NODE_LEGACY_INITIAL_COMPATIBILITY: &str =
    "legacy_initial_state_first_included_node";

pub(crate) fn selected_flow_node_ref(
    role_selection: &RuntimeConsumptionLaneSelection,
) -> Option<&str> {
    [
        role_selection.execution_plan["team_flow_authority_selected_node_id"].as_str(),
        role_selection.execution_plan["development_flow"]["dispatch_contract"]["selected_node_id"]
            .as_str(),
        role_selection.execution_plan["development_flow"]["dispatch_contract"]
            ["team_flow_authority_selected_node_id"]
            .as_str(),
        role_selection.execution_plan["selected_flow_contract"]["selected_node_id"].as_str(),
    ]
    .into_iter()
    .flatten()
    .map(str::trim)
    .find(|value| !value.is_empty())
}

pub(crate) fn validated_selected_flow_node_ref(
    role_selection: &RuntimeConsumptionLaneSelection,
) -> Result<Option<String>, String> {
    let evidence = [
        role_selection.execution_plan["team_flow_authority_selected_node_id"].as_str(),
        role_selection.execution_plan["development_flow"]["dispatch_contract"]["selected_node_id"]
            .as_str(),
        role_selection.execution_plan["development_flow"]["dispatch_contract"]
            ["team_flow_authority_selected_node_id"]
            .as_str(),
        role_selection.execution_plan["selected_flow_contract"]["selected_node_id"].as_str(),
    ]
    .into_iter()
    .flatten()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .collect::<Vec<_>>();
    let identities = evidence.iter().cloned().collect::<BTreeSet<_>>();
    if identities.len() > 1 {
        return Err(format!(
            "team_flow_selected_node_identity_conflict:{}",
            evidence.join(",")
        ));
    }
    Ok(identities.into_iter().next())
}

pub(crate) fn selected_flow_node_ref_for_mode(
    role_selection: &RuntimeConsumptionLaneSelection,
    authority: &TeamFlowExecutionAuthority,
    fresh: bool,
) -> Result<String, String> {
    if fresh {
        // Fresh execution is config-authoritative: persisted plan identities
        // must not influence the initial node. Replay/persisted paths below
        // retain exact persisted selection semantics.
        let entry_node_id = authority.entry_node_id.trim();
        if !entry_node_id.is_empty() {
            return Ok(entry_node_id.to_string());
        }
        return Err(format!(
            "team_flow_authority_entry_node_missing:{}",
            authority.snapshot.flow_ref
        ));
    }
    if let Some(selected_node_id) = validated_selected_flow_node_ref(role_selection)? {
        return Ok(selected_node_id);
    }
    Err(format!(
        "team_flow_authority_selected_node_id_missing:{}",
        authority.snapshot.flow_ref
    ))
}

fn missing_agent_lane_dispatch_packet_error(dispatch_target: &str) -> String {
    let _ = blocker_code_str(BlockerCode::MissingPacket);
    format!("Agent lane dispatch for `{dispatch_target}` is missing dispatch_packet_path")
}
fn typed_team_flow_command_for_dispatch_target(
    role_selection: &RuntimeConsumptionLaneSelection,
    target: &str,
) -> Option<String> {
    let authority = require_team_flow_authority_for_selection(role_selection).ok()?;
    resolve_team_flow_target_for_selection(&authority, None, target)
        .ok()?
        .command_surface
}

fn strict_team_flow_node_for_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    target: &str,
) -> Result<crate::team_flow_authority_adapter::TeamFlowNodeResolution, String> {
    let authority = require_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    resolve_team_flow_target_for_selection(&authority, None, target).map_err(|blocker| blocker.code)
}

fn selected_team_flow_node_for_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt_dispatch_target: &str,
) -> Result<Option<crate::team_flow_authority_adapter::TeamFlowNodeResolution>, String> {
    let Some(selected_node_id) = selected_flow_node_ref(role_selection) else {
        return Ok(None);
    };
    let authority = require_persisted_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    let selected_node = resolve_team_flow_target_for_selection(
        &authority,
        Some(&role_selection.execution_plan),
        selected_node_id,
    )
    .map_err(|blocker| blocker.code)?;
    let receipt_dispatch_target = receipt_dispatch_target.trim();
    let receipt_node = resolve_team_flow_target_for_selection(
        &authority,
        Some(&role_selection.execution_plan),
        receipt_dispatch_target,
    )
    .map_err(|blocker| blocker.code)?;
    if receipt_node.node_id != selected_node.node_id {
        return Err(format!(
            "team_flow_selected_node_dispatch_target_mismatch:{}:{}:{}",
            selected_node.node_id, receipt_dispatch_target, receipt_node.node_id
        ));
    }
    Ok(Some(selected_node))
}

pub(crate) fn authority_dispatch_target_for_runtime_role(
    role_selection: &RuntimeConsumptionLaneSelection,
    runtime_role: &str,
) -> Result<String, String> {
    let authority = require_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    authority
        .resolve_runtime_role(None, runtime_role)
        .map(|node| node.dispatch_target)
        .map_err(|blocker| blocker.code)
}

pub(crate) fn typed_terminal_dispatch_target(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
) -> Result<bool, String> {
    let authority = require_persisted_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    let node = resolve_team_flow_target_for_selection(&authority, None, dispatch_target)
        .map_err(|blocker| blocker.code)?;
    Ok(node.terminal)
}

/// Returns the validated TeamFlow dispatch aliases used by executable callers.
/// Raw `execution_plan.dispatch_contract` sequences are diagnostic-only.
pub(crate) fn typed_lane_sequence(
    role_selection: &RuntimeConsumptionLaneSelection,
    execution_only: bool,
) -> Result<Vec<String>, String> {
    let authority = require_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.to_string())?;
    let sequence = authority
        .ordered_nodes()
        .filter(|node| node.node.included)
        .filter(|node| !execution_only || node.node.inclusion_rule != "design_gate")
        .map(|node| node.dispatch_alias.trim().to_string())
        .filter(|target| !target.is_empty())
        .collect::<Vec<_>>();
    if sequence.is_empty() {
        return Err(
            crate::team_flow_state_machine::DISPATCH_CONTRACT_LANE_CATALOG_INCOMPLETE.to_string(),
        );
    }
    Ok(sequence)
}

/// Returns the authoritative ordered TeamFlow execution nodes.
///
/// Node ids are the only execution identities guaranteed to be unique. Alias
/// projections remain available through `typed_lane_sequence` for diagnostics
/// and compatibility output, but executable callers must resolve node ids.
pub(crate) fn typed_lane_node_sequence(
    role_selection: &RuntimeConsumptionLaneSelection,
    execution_only: bool,
) -> Result<Vec<crate::team_flow_authority_adapter::TeamFlowNodeResolution>, String> {
    let authority = require_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.to_string())?;
    let mut seen = BTreeSet::new();
    let mut sequence = Vec::new();
    for projection in authority
        .ordered_nodes()
        .filter(|node| node.node.included)
        .filter(|node| !execution_only || node.node.inclusion_rule != "design_gate")
    {
        let node_id = projection.node.node_id.trim();
        if node_id.is_empty() {
            return Err("team_flow_node_identity_missing".to_string());
        }
        if !seen.insert(node_id.to_string()) {
            return Err(format!("team_flow_node_identity_ambiguous: {node_id}"));
        }
        sequence.push(
            authority
                .resolve_target(None, node_id)
                .map_err(|blocker| blocker.to_string())?,
        );
    }
    if sequence.is_empty() {
        return Err(
            crate::team_flow_state_machine::DISPATCH_CONTRACT_LANE_CATALOG_INCOMPLETE.to_string(),
        );
    }
    Ok(sequence)
}

pub(crate) fn lawful_explicit_downstream_dispatch_target_for_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    explicit_target: &str,
) -> Result<Option<String>, String> {
    lawful_explicit_downstream_dispatch_target_for_typed_role_selection(
        role_selection,
        &receipt.dispatch_target,
        receipt.downstream_dispatch_last_target.as_deref(),
        explicit_target,
    )
}

pub(crate) fn lawful_explicit_downstream_dispatch_target_for_completed_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    completed_dispatch_target: &str,
    previous_dispatch_target: Option<&str>,
    explicit_target: &str,
) -> Result<Option<String>, String> {
    lawful_explicit_downstream_dispatch_target_for_typed_role_selection(
        role_selection,
        completed_dispatch_target,
        previous_dispatch_target,
        explicit_target,
    )
}

fn lawful_explicit_downstream_dispatch_target_for_typed_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    completed_dispatch_target: &str,
    _previous_dispatch_target: Option<&str>,
    explicit_target: &str,
) -> Result<Option<String>, String> {
    let authority = require_persisted_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    let current = authority
        .resolve_target(
            Some(&role_selection.execution_plan),
            completed_dispatch_target,
        )
        .map_err(|blocker| blocker.code)?;
    let requested = authority
        .resolve_target(None, explicit_target)
        .map_err(|blocker| blocker.code)?;
    Ok(
        (current.next_node.as_deref() == Some(requested.node_id.as_str()))
            .then_some(requested.dispatch_target),
    )
}

pub(crate) fn terminal_closure_downstream_target_for_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Result<Option<String>, String> {
    let _ = typed_lane_sequence(role_selection, false)?;
    let _ = receipt;
    // A validated terminal node has no implicit successor.  Callers must use
    // the authority's explicit `next_node`; this compatibility surface fails
    // closed instead of fabricating a closure target.
    Ok(None)
}

pub(crate) fn downstream_activation_fields(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
) -> (String, Option<String>, Option<String>, Option<String>) {
    let policy_dispatch_target =
        policy_dispatch_target_for_admissibility(&role_selection.execution_plan, dispatch_target);
    if matches!(
        policy_dispatch_target.as_str(),
        "spec-pack" | "work-pool-pack" | "dev-pack"
    ) {
        return (
            "taskflow_pack".to_string(),
            runtime_dispatch_command_for_target(role_selection, &policy_dispatch_target),
            None,
            None,
        );
    }
    if matches!(
        typed_terminal_dispatch_target(role_selection, dispatch_target),
        Ok(true)
    ) {
        return ("closure".to_string(), None, None, None);
    }
    let lane = strict_team_flow_node_for_role_selection(role_selection, dispatch_target)
        .or_else(|_| {
            strict_team_flow_node_for_role_selection(role_selection, &policy_dispatch_target)
        })
        .ok();
    let activation_agent_type = lane.as_ref().and_then(|node| {
        json_string(node.activation.get("activation_agent_type"))
            .or_else(|| json_string(node.assignment.get("activation_agent_type")))
            .or_else(|| json_string(node.assignment.get("selected_tier")))
            .or_else(|| {
                (!node.carrier_tier.trim().is_empty()).then(|| node.carrier_tier.clone())
            })
    });
    let activation_runtime_role = lane.as_ref().and_then(|node| {
        json_string(node.activation.get("activation_runtime_role"))
            .or_else(|| json_string(node.assignment.get("activation_runtime_role")))
            .or_else(|| json_string(node.assignment.get("selected_runtime_role")))
            .or_else(|| json_string(node.assignment.get("runtime_role")))
            .or_else(|| (!node.runtime_role.trim().is_empty()).then(|| node.runtime_role.clone()))
    });
    (
        "agent_lane".to_string(),
        typed_team_flow_command_for_dispatch_target(role_selection, dispatch_target),
        activation_agent_type,
        activation_runtime_role,
    )
}

pub(crate) fn downstream_activation_fields_for_resolved_node(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    dispatch_node: Option<&TeamFlowNodeResolution>,
) -> (String, Option<String>, Option<String>, Option<String>) {
    let Some(dispatch_node) = dispatch_node else {
        return downstream_activation_fields(role_selection, dispatch_target);
    };
    if dispatch_node.terminal {
        return ("closure".to_string(), None, None, None);
    }
    (
        "agent_lane".to_string(),
        dispatch_node.command_surface.clone(),
        None,
        None,
    )
}

pub(crate) fn execution_plan_route_for_dispatch_target<'a>(
    execution_plan: &'a serde_json::Value,
    dispatch_target: &str,
) -> Option<&'a serde_json::Value> {
    let requested_dispatch_target = dispatch_target.trim();
    if requested_dispatch_target.is_empty() {
        return None;
    }
    let catalog =
        execution_plan["development_flow"]["dispatch_contract"]["lane_catalog"].as_object()?;
    if let Some(route) = catalog.get(requested_dispatch_target) {
        return Some(route);
    }
    let canonical = canonical_dispatch_target_name(requested_dispatch_target);
    if let Some(route) = catalog.get(&canonical) {
        return Some(route);
    }
    let mut matches = catalog.values().filter(|route| {
        ["dispatch_target", "dispatch_alias", "lane_id", "node_id"]
            .iter()
            .filter_map(|field| route.get(*field).and_then(serde_json::Value::as_str))
            .any(|value| {
                value == requested_dispatch_target
                    || canonical_dispatch_target_name(value) == canonical
            })
    });
    let route = matches.next()?;
    matches.next().is_none().then_some(route)
}

fn canonical_runtime_assignment_for_route(route: &serde_json::Value) -> Option<serde_json::Value> {
    let raw = crate::taskflow_routing::runtime_assignment_from_route(route);
    let mut assignment = raw.as_object()?.clone();
    let copy_alias = |object: &mut serde_json::Map<String, serde_json::Value>,
                      canonical: &str,
                      aliases: &[&str]| {
        if object
            .get(canonical)
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
        {
            return;
        }
        if let Some(value) = aliases.iter().find_map(|alias| object.get(*alias).cloned()) {
            object.insert(canonical.to_string(), value);
        }
    };
    copy_alias(
        &mut assignment,
        "selected_carrier_id",
        &["carrier_id", "carrier"],
    );
    copy_alias(
        &mut assignment,
        "selected_model_profile_id",
        &[
            "model_profile_id",
            "default_model_profile",
            "selected_profile",
        ],
    );
    copy_alias(
        &mut assignment,
        "selected_model_ref",
        &["model_ref", "selected_model"],
    );
    if assignment
        .get("selected_model_ref")
        .and_then(serde_json::Value::as_str)
        .is_none_or(|value| value.trim().is_empty())
    {
        if let Some(value) = route
            .get("selected_model_profile")
            .and_then(|profile| profile.get("model_ref").or_else(|| profile.get("model")))
            .cloned()
        {
            assignment.insert("selected_model_ref".to_string(), value);
        }
    }
    if assignment
        .get("selected_reasoning_effort")
        .and_then(serde_json::Value::as_str)
        .is_none_or(|value| value.trim().is_empty())
    {
        if let Some(value) = route
            .get("selected_model_profile")
            .and_then(|profile| {
                profile
                    .get("reasoning_effort")
                    .or_else(|| profile.get("model_reasoning_effort"))
            })
            .cloned()
        {
            assignment.insert("selected_reasoning_effort".to_string(), value);
        }
    }
    copy_alias(
        &mut assignment,
        "selected_backend_id",
        &["backend_id", "executor_backend_id"],
    );
    if assignment
        .get("selected_backend_id")
        .and_then(serde_json::Value::as_str)
        .is_none_or(|value| value.trim().is_empty())
    {
        if let Some(value) = route
            .get("executor_backend_relation")
            .and_then(|relation| relation.get("selected_id"))
            .cloned()
        {
            assignment.insert("selected_backend_id".to_string(), value);
        }
    }
    copy_alias(&mut assignment, "selected_runtime_role", &["runtime_role"]);
    copy_alias(&mut assignment, "task_class", &["route_task_class"]);
    if assignment
        .get("selected_runtime_role")
        .and_then(serde_json::Value::as_str)
        .is_none_or(|value| value.trim().is_empty())
    {
        if let Some(value) = route.get("runtime_role").cloned() {
            assignment.insert("selected_runtime_role".to_string(), value);
        }
    }
    if assignment
        .get("task_class")
        .and_then(serde_json::Value::as_str)
        .is_none_or(|value| value.trim().is_empty())
    {
        if let Some(value) = route.get("task_class").cloned() {
            assignment.insert("task_class".to_string(), value);
        }
    }
    authoritative_runtime_assignment_candidate(&serde_json::Value::Object(assignment))
}

fn non_empty_assignment_string(assignment: &serde_json::Value, key: &str) -> bool {
    assignment
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .is_some_and(|value| !value.is_empty())
}

fn runtime_assignment_has_authoritative_truth(assignment: &serde_json::Value) -> bool {
    if !assignment
        .as_object()
        .is_some_and(|object| !object.is_empty())
    {
        return false;
    }
    if assignment
        .get("enabled")
        .and_then(serde_json::Value::as_bool)
        == Some(false)
    {
        return true;
    }
    let has_backend_selector = [
        "effective_selected_backend",
        "selected_dispatch_backend_id",
        "dispatch_backend_id",
        "selected_backend_id",
    ]
    .iter()
    .any(|key| non_empty_assignment_string(assignment, key));
    let has_model_selector = [
        "selected_model_profile_id",
        "selected_model_ref",
        "model_profile_id",
        "model_ref",
    ]
    .iter()
    .any(|key| non_empty_assignment_string(assignment, key));
    has_backend_selector && has_model_selector
}

fn authoritative_runtime_assignment_candidate(
    assignment: &serde_json::Value,
) -> Option<serde_json::Value> {
    runtime_assignment_has_authoritative_truth(assignment).then(|| assignment.clone())
}

pub(crate) fn dispatch_target_runtime_assignment(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> (serde_json::Value, &'static str) {
    let requested_dispatch_target = dispatch_target.trim();
    if requested_dispatch_target.is_empty() {
        return (serde_json::Value::Null, "missing");
    }
    {
        let dispatch_target = requested_dispatch_target;
        if let Some((assignment, source)) =
            execution_plan_route_for_dispatch_target(execution_plan, dispatch_target).and_then(
                |route| {
                    canonical_runtime_assignment_for_route(route).map(|assignment| {
                        let source = if route.get("carrier_runtime_assignment").is_some() {
                            "route_carrier_runtime_assignment"
                        } else {
                            "route_runtime_assignment"
                        };
                        (assignment, source)
                    })
                },
            )
        {
            return (assignment, source);
        }

        if let Some((assignment, source)) =
            execution_plan_route_for_dispatch_target(execution_plan, dispatch_target)
                .and_then(|lane| lane.get("activation"))
                .and_then(|activation| {
                    authoritative_runtime_assignment_candidate(activation)
                        .map(|assignment| (assignment, "team_flow_activation_assignment"))
                })
        {
            return (assignment, source);
        }

        if let Some((assignment, source)) = execution_plan
            .get("development_flow")
            .and_then(|flow| flow.get("dispatch_contract"))
            .and_then(|dispatch_contract| {
                let (activation_key, assignment_source) = match dispatch_target {
                    "specification" | "development_specification" => (
                        "specification_activation",
                        "dispatch_contract_specification_activation",
                    ),
                    "implementer" | "development_implementer" => (
                        "implementer_activation",
                        "dispatch_contract_implementer_activation",
                    ),
                    "coach" | "development_coach" => (
                        "coach_activation",
                        "dispatch_contract_coach_activation",
                    ),
                    "tester" | "verification" | "development_verifier" => (
                        "verification_activation",
                        "dispatch_contract_verification_activation",
                    ),
                    "architect" | "development_architecture" => (
                        "architecture_activation",
                        "dispatch_contract_architecture_activation",
                    ),
                    _ => return None,
                };
                dispatch_contract
                    .get(activation_key)
                    .and_then(authoritative_runtime_assignment_candidate)
                    .map(|assignment| (assignment, assignment_source))
            })
        {
            return (assignment, source);
        }
    }

    (serde_json::Value::Null, "missing")
}

fn backend_admissibility_context_for_dispatch_target<'a>(
    execution_plan: &'a serde_json::Value,
    dispatch_target: &str,
) -> (String, Option<DispatchContractLane<'a>>) {
    let requested_dispatch_target = dispatch_target.trim();
    let lane = execution_plan_route_for_dispatch_target(execution_plan, requested_dispatch_target)
        .map(DispatchContractLane::from_value);
    (requested_dispatch_target.to_string(), lane)
}

fn dispatch_target_requires_strict_backend_admissibility(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> bool {
    let (canonical_dispatch_target, _) =
        backend_admissibility_context_for_dispatch_target(execution_plan, dispatch_target);
    crate::runtime_assignment_policy::backend_admissibility_requires_strict_dispatch_target(
        &canonical_dispatch_target,
    )
}

pub(crate) fn backend_is_admissible_for_dispatch_target(
    execution_plan: &serde_json::Value,
    backend_id: &str,
    dispatch_target: &str,
) -> bool {
    let (canonical_dispatch_target, lane) =
        backend_admissibility_context_for_dispatch_target(execution_plan, dispatch_target);
    crate::runtime_assignment_policy::backend_is_admissible_for_dispatch_target(
        execution_plan,
        backend_id,
        &canonical_dispatch_target,
        lane.as_ref(),
    )
}

fn assignment_selects_backend(assignment: &serde_json::Value, backend_id: &str) -> bool {
    [
        "effective_selected_backend",
        "selected_dispatch_backend_id",
        "dispatch_backend_id",
        "selected_backend_id",
        "selected_backend",
    ]
    .iter()
    .filter_map(|key| json_string(assignment.get(*key)))
    .any(|value| value.trim() == backend_id)
}

fn assignment_selects_explicit_dispatch_backend(
    execution_plan: &serde_json::Value,
    assignment: &serde_json::Value,
    backend_id: &str,
) -> bool {
    let explicit_match = [
        "effective_selected_backend",
        "selected_dispatch_backend_id",
        "dispatch_backend_id",
        "selected_backend_id",
        "selected_backend",
    ]
    .iter()
    .filter_map(|key| json_string(assignment.get(*key)))
    .any(|value| value.trim() == backend_id);
    explicit_match && backend_has_execution_plan_dispatch_metadata(execution_plan, backend_id)
}

fn backend_has_execution_plan_dispatch_metadata(
    execution_plan: &serde_json::Value,
    backend_id: &str,
) -> bool {
    backend_admissibility_row(execution_plan, backend_id).is_some_and(|row| {
        row["backend_class"]
            .as_str()
            .map(str::trim)
            .is_some_and(|value| !value.is_empty())
            || row["lane_admissibility"].as_object().is_some()
    })
}

fn backend_admissibility_class<'a>(
    execution_plan: &'a serde_json::Value,
    backend_id: &str,
) -> Option<&'a str> {
    backend_admissibility_row(execution_plan, backend_id)
        .and_then(|row| row["backend_class"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn assignment_is_internal_host_carrier(
    execution_plan: &serde_json::Value,
    assignment: &serde_json::Value,
    backend_id: &str,
) -> bool {
    if backend_id.trim().is_empty() || !assignment_selects_backend(assignment, backend_id) {
        return false;
    }
    let backend_class = backend_admissibility_class(execution_plan, backend_id);
    if matches!(backend_class, Some("external_cli" | "external")) {
        return false;
    }
    if matches!(backend_class, Some("internal" | "internal_cli")) {
        return true;
    }
    if backend_class.is_none() {
        return false;
    }
    let provider = json_string(assignment.get("selected_model_provider"))
        .or_else(|| json_string(assignment.get("model_provider")))
        .unwrap_or_default();
    matches!(provider.as_str(), "openai" | "internal")
        || assignment.get("selected_model_profile_id").is_some()
}

pub(crate) fn backend_is_admissible_or_runtime_selected_carrier_for_dispatch_target(
    execution_plan: &serde_json::Value,
    backend_id: &str,
    dispatch_target: &str,
) -> bool {
    backend_is_admissible_for_dispatch_target(execution_plan, backend_id, dispatch_target)
}

#[cfg(test)]
fn route_selected_backend(
    execution_plan: &serde_json::Value,
    route: &serde_json::Value,
) -> Option<String> {
    selected_backend_from_execution_plan_route(execution_plan, route)
}

#[cfg(test)]
fn route_selected_backend_for_dispatch_target(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> Option<String> {
    admissible_selected_backend_for_dispatch_target(execution_plan, dispatch_target, None, None)
        .or_else(|| {
            execution_plan_route_for_dispatch_target(execution_plan, dispatch_target)
                .and_then(|route| route_selected_backend(execution_plan, route))
        })
}

fn route_has_backend_hints(execution_plan: &serde_json::Value, route: &serde_json::Value) -> bool {
    let _ = execution_plan;
    route_primary_backend_hint_from_route(route).is_some()
        || fallback_executor_backend_from_route(route).is_some()
        || !fanout_executor_backends_from_route(route).is_empty()
}

fn admissible_backend_candidates_for_dispatch_target(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
    route: &serde_json::Value,
    inherited_selected_backend: Option<&str>,
    activation_agent_type: Option<&str>,
) -> Vec<String> {
    let route_is_backend_agnostic = !route_has_backend_hints(execution_plan, route);
    let strict_required =
        dispatch_target_requires_strict_backend_admissibility(execution_plan, dispatch_target);
    let mut candidates = Vec::new();
    let inherited = inherited_selected_backend.map(str::to_string);
    let activation = activation_agent_type.map(str::to_string);
    let (_, target_assignment_source) =
        dispatch_target_runtime_assignment(execution_plan, dispatch_target);
    let explicit_runtime_assignment_backend =
        explicit_runtime_assignment_selected_backend_for_target(execution_plan, dispatch_target);
    let target_assignment_is_route_scoped = matches!(
        target_assignment_source,
        "route_carrier_runtime_assignment" | "route_runtime_assignment"
    ) || (target_assignment_source
        .starts_with("dispatch_contract_")
        && explicit_runtime_assignment_backend.is_some());
    let route_primary = route_primary_backend_hint_from_route(route);
    let route_fallback = fallback_executor_backend_from_route(route);
    let route_fanout = fanout_executor_backends_from_route(route);
    let runtime_assignment_backend = explicit_runtime_assignment_backend.filter(|backend_id| {
        if target_assignment_is_route_scoped || (!strict_required && route_is_backend_agnostic) {
            return true;
        }
        !strict_required && backend_has_execution_plan_dispatch_metadata(execution_plan, backend_id)
    });
    let has_explicit_runtime_assignment_backend =
        runtime_assignment_backend.is_some() && target_assignment_is_route_scoped;
    let route_backends_have_dispatch_metadata = route_primary
        .iter()
        .chain(route_fallback.iter())
        .chain(route_fanout.iter())
        .any(|backend_id| {
            backend_policy_from_execution_plan(execution_plan, backend_id).is_some()
                || backend_has_execution_plan_dispatch_metadata(execution_plan, backend_id)
        });
    let prefer_route_backends_first = !route_is_backend_agnostic
        && (strict_required || route_backends_have_dispatch_metadata || inherited.is_none());
    if !strict_required {
        if let Some(runtime_assignment_backend) = runtime_assignment_backend.as_ref() {
            candidates.push(runtime_assignment_backend.clone());
        }
    }
    if !strict_required && !prefer_route_backends_first {
        if let Some(inherited) = inherited.as_ref() {
            candidates.push(inherited.clone());
        }
    }
    if prefer_route_backends_first {
        if !strict_required {
            if let Some(runtime_assignment_backend) = runtime_assignment_backend
                .as_ref()
                .filter(|_| has_explicit_runtime_assignment_backend)
            {
                candidates.push(runtime_assignment_backend.clone());
            }
        }
        if let Some(primary) = route_primary.as_ref() {
            candidates.push(primary.clone());
        }
        if strict_required {
            if let Some(runtime_assignment_backend) = runtime_assignment_backend.as_ref() {
                candidates.push(runtime_assignment_backend.clone());
            }
        }
        if let Some(fallback) = route_fallback.as_ref() {
            candidates.push(fallback.clone());
        }
        candidates.extend(route_fanout.iter().cloned());
    }
    if !strict_required && prefer_route_backends_first {
        if let Some(runtime_assignment_backend) = runtime_assignment_backend
            .as_ref()
            .filter(|_| !has_explicit_runtime_assignment_backend)
        {
            candidates.push(runtime_assignment_backend.clone());
        }
        if let Some(inherited) = inherited.as_ref() {
            candidates.push(inherited.clone());
        }
    }
    if strict_required {
        if let Some(activation) = activation.as_ref() {
            candidates.push(activation.clone());
        }
    }
    if strict_required {
        if let Some(runtime_assignment_backend) = runtime_assignment_backend.as_ref() {
            candidates.push(runtime_assignment_backend.clone());
        }
    }
    if strict_required {
        if let Some(inherited) = inherited {
            candidates.push(inherited);
        }
    }
    if !prefer_route_backends_first && !route_is_backend_agnostic {
        if let Some(primary) = route_primary.as_ref() {
            candidates.push(primary.clone());
        }
        if let Some(fallback) = route_fallback.as_ref() {
            candidates.push(fallback.clone());
        }
        candidates.extend(route_fanout.iter().cloned());
    }
    if let Some(activation) = activation.filter(|_| route_is_backend_agnostic && !strict_required) {
        candidates.push(activation);
    }
    let mut unique = std::collections::BTreeSet::new();
    candidates
        .into_iter()
        .filter(|candidate| !candidate.trim().is_empty())
        .filter(|candidate| unique.insert(candidate.clone()))
        .collect()
}

pub(crate) fn admissible_selected_backend_for_dispatch_target(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
    activation_agent_type: Option<&str>,
    inherited_selected_backend: Option<&str>,
) -> Option<String> {
    let strict_required =
        dispatch_target_requires_strict_backend_admissibility(execution_plan, dispatch_target);
    let route = execution_plan_route_for_dispatch_target(execution_plan, dispatch_target);
    let (candidates, _route_is_backend_agnostic) = if let Some(route) = route {
        (
            admissible_backend_candidates_for_dispatch_target(
                execution_plan,
                dispatch_target,
                route,
                inherited_selected_backend,
                activation_agent_type,
            ),
            !route_has_backend_hints(execution_plan, route),
        )
    } else {
        let mut unique = std::collections::BTreeSet::new();
        (
            inherited_selected_backend
                .into_iter()
                .chain(activation_agent_type)
                .map(str::trim)
                .filter(|candidate| !candidate.is_empty())
                .filter(|candidate| unique.insert((*candidate).to_string()))
                .map(str::to_string)
                .collect::<Vec<_>>(),
            true,
        )
    };
    let route_activation_backend = route.and_then(activation_backend_from_route);
    let explicit_route_policy_backends = route
        .map(|route| {
            route_primary_backend_hint_from_route(route)
                .into_iter()
                .chain(fallback_executor_backend_from_route(route))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let has_backend_admissibility_matrix = execution_plan["backend_admissibility_matrix"]
        .as_array()
        .map(|rows| !rows.is_empty())
        .unwrap_or(false);
    if !strict_required {
        return candidates.into_iter().next();
    }
    let selected = candidates.into_iter().find(|candidate| {
        backend_is_admissible_or_runtime_selected_carrier_for_dispatch_target(
            execution_plan,
            candidate,
            dispatch_target,
        ) || (!has_backend_admissibility_matrix
            && explicit_route_policy_backends
                .iter()
                .any(|backend| backend == candidate))
            || route_activation_backend.as_deref() == Some(candidate.as_str())
    });
    selected
        .or_else(|| admissible_matrix_backend_for_dispatch_target(execution_plan, dispatch_target))
}

fn admissible_matrix_backend_for_dispatch_target(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> Option<String> {
    let matrix = execution_plan["backend_admissibility_matrix"].as_array()?;
    matrix
        .iter()
        .filter_map(|row| {
            row["backend_id"]
                .as_str()
                .map(|backend_id| (backend_id, row))
        })
        .filter(|(backend_id, _)| {
            backend_is_admissible_for_dispatch_target(execution_plan, backend_id, dispatch_target)
        })
        .max_by_key(|(_, row)| {
            (
                row["backend_class"].as_str() == Some("internal"),
                row["write_scope"].as_str() == Some("orchestrator_native"),
            )
        })
        .map(|(backend_id, _)| backend_id.to_string())
}

pub(crate) fn downstream_selected_backend(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    activation_agent_type: Option<&str>,
    inherited_selected_backend: Option<&str>,
) -> Option<String> {
    let _ = activation_agent_type;
    let _ = inherited_selected_backend;
    explicit_runtime_assignment_selected_backend_for_target(
        &role_selection.execution_plan,
        dispatch_target,
    )
    .filter(|backend_id| {
        backend_is_admissible_for_dispatch_target(
            &role_selection.execution_plan,
            backend_id,
            dispatch_target,
        )
    })
}

pub(crate) fn downstream_selected_backend_for_resolved_node(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_node: Option<&TeamFlowNodeResolution>,
    dispatch_target: &str,
    activation_agent_type: Option<&str>,
    inherited_selected_backend: Option<&str>,
) -> Option<String> {
    dispatch_node
        .and_then(|node| {
            node.executor_backend_relation
                .get("selected_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
        .or_else(|| {
            downstream_selected_backend(
                role_selection,
                dispatch_target,
                activation_agent_type,
                inherited_selected_backend,
            )
        })
}

fn backend_admissibility_row<'a>(
    execution_plan: &'a serde_json::Value,
    backend_id: &str,
) -> Option<&'a serde_json::Value> {
    execution_plan["backend_admissibility_matrix"]
        .as_array()
        .into_iter()
        .flatten()
        .find(|row| row["backend_id"].as_str() == Some(backend_id))
}

fn backend_class_for_execution_plan_backend(
    execution_plan: &serde_json::Value,
    backend_id: &str,
) -> String {
    if backend_id.trim().is_empty() {
        return "unknown".to_string();
    }
    backend_admissibility_row(execution_plan, backend_id)
        .and_then(|row| row["backend_class"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| "unknown".to_string())
}

fn backend_execution_dimension(backend_class: &str) -> &'static str {
    match backend_class.trim() {
        "external_cli" | "external" => "external",
        "internal" | "internal_cli" => "internal",
        "taskflow_pack" => "taskflow_pack",
        _ => "unknown",
    }
}

pub(crate) fn effective_execution_posture_summary(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
    selected_backend: Option<&str>,
    activation_agent_type: Option<&str>,
    host_runtime: Option<&serde_json::Value>,
    receipt_backed_execution_evidence: bool,
    selected_backend_override: Option<&str>,
) -> serde_json::Value {
    let route = execution_plan_route_for_dispatch_target(execution_plan, dispatch_target);
    let route_primary_backend = route.and_then(route_primary_backend_hint_from_route);
    let runtime_assignment_backend =
        route.and_then(|route| runtime_assignment_backend_for_route(execution_plan, route));
    let fallback_backend = route.and_then(fallback_executor_backend_from_route);
    let fanout_backends = route
        .map(fanout_executor_backends_from_route)
        .unwrap_or_default();
    let normalized_selected_backend = selected_backend
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let explicit_selected_backend_override = selected_backend_override
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let effective_selected_backend = explicit_selected_backend_override
        .map(str::to_string)
        .or_else(|| {
            admissible_selected_backend_for_dispatch_target(
                execution_plan,
                dispatch_target,
                activation_agent_type,
                normalized_selected_backend,
            )
        })
        .or_else(|| normalized_selected_backend.map(str::to_string));
    let selected_backend_source = backend_selection_source(
        effective_selected_backend.as_deref(),
        normalized_selected_backend,
        runtime_assignment_backend.as_deref(),
        route_primary_backend.as_deref(),
        fallback_backend.as_deref(),
        &fanout_backends,
        activation_agent_type,
        explicit_selected_backend_override,
    );
    let host_execution_class = host_runtime
        .and_then(|value| value.get("selected_cli_execution_class"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("unknown");
    let selected_backend_class = effective_selected_backend.as_deref().map(|backend_id| {
        let resolved = backend_class_for_execution_plan_backend(execution_plan, backend_id);
        if resolved == "unknown"
            && host_execution_class == "internal"
            && activation_agent_type == Some(backend_id)
        {
            "internal".to_string()
        } else {
            resolved
        }
    });
    let route_primary_backend_class = route_primary_backend
        .as_deref()
        .map(|backend_id| backend_class_for_execution_plan_backend(execution_plan, backend_id));
    let fallback_backend_class = fallback_backend
        .as_deref()
        .map(|backend_id| backend_class_for_execution_plan_backend(execution_plan, backend_id));
    let fanout_backend_classes = fanout_backends
        .iter()
        .map(|backend_id| {
            (
                backend_id.clone(),
                serde_json::Value::String(backend_class_for_execution_plan_backend(
                    execution_plan,
                    backend_id,
                )),
            )
        })
        .collect::<serde_json::Map<String, serde_json::Value>>();

    let route_dimensions = route_primary_backend_class
        .iter()
        .chain(fallback_backend_class.iter())
        .map(|value| backend_execution_dimension(value))
        .chain(
            fanout_backend_classes
                .values()
                .filter_map(serde_json::Value::as_str)
                .map(backend_execution_dimension),
        )
        .collect::<std::collections::BTreeSet<_>>();
    let route_contains_internal_backend = route_dimensions.contains("internal");
    let route_contains_external_backend = route_dimensions.contains("external");
    let mixed_route_backends = route_contains_internal_backend && route_contains_external_backend;

    let selected_execution_class = host_runtime
        .and_then(|value| value.get("selected_cli_execution_class"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let selected_cli_system = host_runtime
        .and_then(|value| value.get("selected_cli_system"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let host_execution_dimension = host_execution_class;
    let selected_backend_dimension = selected_backend_class
        .as_deref()
        .map(backend_execution_dimension)
        .unwrap_or("unknown");
    let hybrid_host_backend_selection = matches!(
        (host_execution_dimension, selected_backend_dimension),
        ("internal", "external") | ("external", "internal")
    );
    let effective_posture_kind = if hybrid_host_backend_selection || mixed_route_backends {
        "mixed"
    } else if selected_backend_dimension == "external" || host_execution_dimension == "external" {
        "external"
    } else if selected_backend_dimension == "internal" || host_execution_dimension == "internal" {
        "internal"
    } else if selected_backend_dimension == "taskflow_pack" {
        "taskflow_pack"
    } else {
        "unknown"
    };

    serde_json::json!({
        "dispatch_target": dispatch_target,
        "selected_cli_system": selected_cli_system,
        "selected_execution_class": selected_execution_class,
        "selected_backend": effective_selected_backend,
        "selected_backend_source": selected_backend_source,
        "backend_selection_source": selected_backend_source,
        "selected_backend_class": selected_backend_class,
        "route_primary_backend": route_primary_backend,
        "route_primary_backend_class": route_primary_backend_class,
        "fallback_backend": fallback_backend,
        "fallback_backend_class": fallback_backend_class,
        "fanout_backends": fanout_backends,
        "fanout_backend_classes": fanout_backend_classes,
        "route_contains_internal_backend": route_contains_internal_backend,
        "route_contains_external_backend": route_contains_external_backend,
        "mixed_route_backends": mixed_route_backends,
        "hybrid_host_backend_selection": hybrid_host_backend_selection,
        "effective_posture_kind": effective_posture_kind,
        "activation_evidence_state": if receipt_backed_execution_evidence {
            "execution_evidence"
        } else {
            "activation_view_only"
        },
        "receipt_backed_execution_evidence": receipt_backed_execution_evidence,
    })
}
fn receipt_selected_backend_matching_configured_route(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    let selected_backend = receipt
        .selected_backend
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let configured_backend = execution_plan_route_for_dispatch_target(
        &role_selection.execution_plan,
        &receipt.dispatch_target,
    )
    .and_then(route_primary_backend_hint_from_route)
    .or_else(|| {
        role_selection.execution_plan["development_flow"]
            .get(&receipt.dispatch_target)
            .and_then(|route| json_string(route.get("executor_backend")))
    })?;
    (configured_backend.trim() == selected_backend
        && backend_is_admissible_for_dispatch_target(
            &role_selection.execution_plan,
            selected_backend,
            &receipt.dispatch_target,
        ))
    .then(|| selected_backend.to_string())
}
fn receipt_selected_external_backend(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    let selected_backend = receipt
        .selected_backend
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let backend_class =
        backend_class_for_execution_plan_backend(&role_selection.execution_plan, selected_backend);
    let plan_external = matches!(backend_execution_dimension(&backend_class), "external")
        && backend_has_execution_plan_dispatch_metadata(
            &role_selection.execution_plan,
            selected_backend,
        );
    let packet_external = receipt
        .dispatch_packet_path
        .as_deref()
        .into_iter()
        .flat_map(|path| Path::new(path).ancestors())
        .find_map(|project_root| {
            let overlay = load_project_overlay_yaml_for_root(project_root).ok()?;
            configured_external_backend_entry(&overlay, selected_backend).map(|_| ())
        })
        .is_some();
    let matrix_admissible = backend_is_admissible_for_dispatch_target(
        &role_selection.execution_plan,
        selected_backend,
        &receipt.dispatch_target,
    );
    (matrix_admissible && (plan_external || packet_external)).then(|| selected_backend.to_string())
}

pub(crate) fn canonical_selected_backend_for_receipt(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    receipt_selected_external_backend(role_selection, receipt)
        .or_else(|| receipt_selected_backend_matching_configured_route(role_selection, receipt))
}

pub(crate) fn sync_receipt_configured_activation_assignment(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &mut crate::state_store::RunGraphDispatchReceipt,
) {
    if receipt.dispatch_kind != "agent_lane" {
        return;
    }
    let execution_plan = &role_selection.execution_plan;
    let policy_target =
        policy_dispatch_target_for_admissibility(execution_plan, &receipt.dispatch_target);
    let Ok(canonical_target) =
        authority_dispatch_target_for_runtime_role(role_selection, &policy_target)
    else {
        return;
    };
    let lane_activation =
        strict_team_flow_node_for_role_selection(role_selection, &canonical_target)
            .ok()
            .map(|node| node.activation);
    let (assignment, _) =
        dispatch_target_runtime_assignment(execution_plan, &receipt.dispatch_target);
    if receipt.activation_agent_type.is_none() {
        receipt.activation_agent_type = lane_activation
            .as_ref()
            .and_then(|activation| json_string(activation.get("activation_agent_type")))
            .or_else(|| json_string(assignment.get("activation_agent_type")))
            .or_else(|| json_string(assignment.get("selected_tier")))
    }
    if receipt.activation_runtime_role.is_none() {
        receipt.activation_runtime_role = lane_activation
            .as_ref()
            .and_then(|activation| json_string(activation.get("activation_runtime_role")))
            .or_else(|| json_string(assignment.get("activation_runtime_role")))
            .or_else(|| json_string(assignment.get("runtime_role")));
    }
    let selected_backend = canonical_selected_backend_for_receipt(role_selection, receipt)
        .or_else(|| json_string(assignment.get("selected_dispatch_backend_id")))
        .or_else(|| json_string(assignment.get("dispatch_backend_id")))
        .or_else(|| json_string(assignment.get("selected_backend_id")))
        .or_else(|| json_string(assignment.get("selected_backend")))
        .filter(|backend_id| {
            backend_is_admissible_for_dispatch_target(
                execution_plan,
                backend_id,
                &receipt.dispatch_target,
            )
        });
    if let Some(selected_backend) = selected_backend {
        if receipt
            .selected_backend
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty() && *value != "unknown")
            .is_none()
        {
            receipt.selected_backend = Some(selected_backend);
        }
    }
}

fn persisted_selected_backend_override_for_packet_path(packet_path: &str) -> Option<String> {
    crate::read_json_file_if_present(Path::new(packet_path)).and_then(|packet| {
        packet
            .get("selected_backend_override")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    })
}

fn runtime_assignment_selected_backend_for_target(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> Option<String> {
    explicit_runtime_assignment_selected_backend_for_target(execution_plan, dispatch_target)
}

fn explicit_runtime_assignment_selected_backend_for_target(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
) -> Option<String> {
    let (assignment, _) = dispatch_target_runtime_assignment(execution_plan, dispatch_target);
    json_string(assignment.get("effective_selected_backend"))
        .or_else(|| json_string(assignment.get("selected_dispatch_backend_id")))
        .or_else(|| json_string(assignment.get("dispatch_backend_id")))
        .or_else(|| json_string(assignment.get("selected_backend_id")))
        .or_else(|| json_string(assignment.get("selected_backend")))
}

fn selected_backend_override_conflicts_with_runtime_assignment(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    selected_backend_override: &str,
) -> bool {
    let Some(assignment_backend) = runtime_assignment_selected_backend_for_target(
        &role_selection.execution_plan,
        dispatch_target,
    ) else {
        return false;
    };
    if assignment_backend == selected_backend_override {
        return false;
    }
    let override_backend_class = backend_class_for_execution_plan_backend(
        &role_selection.execution_plan,
        selected_backend_override,
    );
    matches!(
        backend_execution_dimension(&override_backend_class),
        "internal"
    ) || selected_backend_override == "internal_subagents"
}

fn current_selected_backend_override<'a>(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    selected_backend_override: Option<&'a str>,
) -> Option<&'a str> {
    selected_backend_override
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .filter(|value| {
            !selected_backend_override_conflicts_with_runtime_assignment(
                role_selection,
                dispatch_target,
                value,
            )
        })
}

pub(crate) fn preferred_selected_backend_for_receipt(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    let selected_backend_override = receipt
        .dispatch_packet_path
        .as_deref()
        .and_then(persisted_selected_backend_override_for_packet_path)
        .and_then(|value| {
            current_selected_backend_override(
                role_selection,
                &receipt.dispatch_target,
                Some(value.as_str()),
            )
            .map(str::to_string)
        });
    selected_backend_override
        .or_else(|| canonical_selected_backend_for_receipt(role_selection, receipt))
        .or_else(|| {
            runtime_assignment_selected_backend_for_target(
                &role_selection.execution_plan,
                &receipt.dispatch_target,
            )
        })
        .or_else(|| receipt.selected_backend.clone())
}

fn preferred_selected_model_profile_for_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
) -> Option<&str> {
    role_selection
        .execution_plan
        .get("runtime_assignment")
        .and_then(|value| value.get("selected_model_profile_id"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

pub(crate) fn route_selected_model_profile_for_backend(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
    backend_id: &str,
) -> Option<String> {
    let backend_id = backend_id.trim();
    if backend_id.is_empty() {
        return None;
    }
    let dispatch_target = policy_dispatch_target_for_admissibility(execution_plan, dispatch_target);
    let dispatch_target = dispatch_target.as_str();
    if dispatch_target == "analysis" {
        if let Some(profile) = execution_plan["development_flow"]
            .get("analysis")
            .filter(|value| !value.is_null())
            .and_then(|route| route.get("profiles"))
            .and_then(|profiles| {
                profiles
                    .get(backend_id)
                    .and_then(serde_json::Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .map(str::to_string)
                    .or_else(|| {
                        profiles
                            .as_str()
                            .map(str::trim)
                            .filter(|value| !value.is_empty())
                            .map(str::to_string)
                    })
            })
        {
            return Some(profile);
        }
    }
    let route = execution_plan_route_for_dispatch_target(execution_plan, dispatch_target)?;
    let profiles = route.get("profiles")?;
    profiles
        .get(backend_id)
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| {
            profiles
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
}

pub(crate) fn preferred_selected_model_profile_for_dispatch_target(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    selected_backend: Option<&str>,
) -> Option<String> {
    let dispatch_target =
        policy_dispatch_target_for_admissibility(&role_selection.execution_plan, dispatch_target);
    selected_backend
        .and_then(|backend_id| {
            route_selected_model_profile_for_backend(
                &role_selection.execution_plan,
                &dispatch_target,
                backend_id,
            )
        })
        .or_else(|| {
            preferred_selected_model_profile_for_role_selection(role_selection).map(str::to_string)
        })
}

fn backend_policy_from_execution_plan<'a>(
    execution_plan: &'a serde_json::Value,
    backend_id: &str,
) -> Option<&'a serde_json::Value> {
    execution_plan["backend_admissibility_matrix"]
        .as_array()
        .into_iter()
        .flatten()
        .find(|entry| entry["backend_id"].as_str() == Some(backend_id))
}

fn backend_class_from_execution_plan(
    execution_plan: &serde_json::Value,
    backend_id: &str,
) -> Option<String> {
    backend_policy_from_execution_plan(execution_plan, backend_id)
        .and_then(|entry| entry["backend_class"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn backend_class_is_internal(backend_class: Option<&str>) -> bool {
    backend_class.is_some_and(|value| matches!(value.trim(), "internal" | "internal_cli"))
}

fn route_execution_posture_from_classes(classes: &[String]) -> &'static str {
    let has_internal = classes.iter().any(|value| value == "internal");
    let has_external = classes.iter().any(|value| value == "external_cli");
    match (has_internal, has_external) {
        (true, true) => "hybrid",
        (true, false) => "internal_only",
        (false, true) => "external_only",
        _ => "unknown",
    }
}

pub(crate) fn dispatch_execution_route_summary(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    selected_backend: Option<&str>,
    selected_backend_override: Option<&str>,
) -> serde_json::Value {
    let route =
        execution_plan_route_for_dispatch_target(&role_selection.execution_plan, dispatch_target);
    let route_primary_backend = route.and_then(route_primary_backend_hint_from_route);
    let runtime_assignment_backend = route.and_then(|route| {
        runtime_assignment_backend_for_route(&role_selection.execution_plan, route)
    });
    let route_fallback_backend = route.and_then(fallback_executor_backend_from_route);
    let route_fanout_backends = route
        .map(fanout_executor_backends_from_route)
        .unwrap_or_default();
    let normalized_selected_backend = selected_backend
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let explicit_selected_backend_override = selected_backend_override
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let effective_selected_backend = explicit_selected_backend_override
        .map(str::to_string)
        .or_else(|| {
            admissible_selected_backend_for_dispatch_target(
                &role_selection.execution_plan,
                dispatch_target,
                None,
                normalized_selected_backend,
            )
        });
    let selected_backend_source = backend_selection_source(
        effective_selected_backend.as_deref(),
        normalized_selected_backend,
        runtime_assignment_backend.as_deref(),
        route_primary_backend.as_deref(),
        route_fallback_backend.as_deref(),
        &route_fanout_backends,
        None,
        explicit_selected_backend_override,
    );

    let mut execution_classes = Vec::new();
    for backend_id in effective_selected_backend
        .iter()
        .chain(route_primary_backend.iter())
        .chain(route_fallback_backend.iter())
        .chain(route_fanout_backends.iter())
    {
        if let Some(class) =
            backend_class_from_execution_plan(&role_selection.execution_plan, backend_id)
        {
            if !execution_classes.iter().any(|existing| existing == &class) {
                execution_classes.push(class);
            }
        }
    }
    let effective_execution_posture = route_execution_posture_from_classes(&execution_classes);
    let selected_backend_class = effective_selected_backend
        .as_deref()
        .and_then(|backend_id| {
            backend_class_from_execution_plan(&role_selection.execution_plan, backend_id)
        });
    let route_primary_backend_class = route_primary_backend.as_deref().and_then(|backend_id| {
        backend_class_from_execution_plan(&role_selection.execution_plan, backend_id)
    });
    let route_fallback_backend_class = route_fallback_backend.as_deref().and_then(|backend_id| {
        backend_class_from_execution_plan(&role_selection.execution_plan, backend_id)
    });
    let route_fanout_backend_classes = route_fanout_backends
        .iter()
        .map(|backend_id| {
            (
                backend_id.clone(),
                serde_json::json!(backend_class_from_execution_plan(
                    &role_selection.execution_plan,
                    backend_id
                )),
            )
        })
        .collect::<serde_json::Map<String, serde_json::Value>>();
    let selected_backend_policy = effective_selected_backend
        .as_deref()
        .and_then(|backend_id| {
            backend_policy_from_execution_plan(&role_selection.execution_plan, backend_id)
        })
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let route_primary_backend_policy = route_primary_backend
        .as_deref()
        .and_then(|backend_id| {
            backend_policy_from_execution_plan(&role_selection.execution_plan, backend_id)
        })
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let route_fallback_backend_policy = route_fallback_backend
        .as_deref()
        .and_then(|backend_id| {
            backend_policy_from_execution_plan(&role_selection.execution_plan, backend_id)
        })
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let route_fanout_backend_policies = route_fanout_backends
        .iter()
        .map(|backend_id| {
            backend_policy_from_execution_plan(&role_selection.execution_plan, backend_id)
                .cloned()
                .unwrap_or_else(|| serde_json::json!({ "backend_id": backend_id }))
        })
        .collect::<Vec<_>>();

    serde_json::json!({
        "dispatch_target": dispatch_target,
        "effective_selected_backend": effective_selected_backend,
        "selected_backend_source": selected_backend_source,
        "backend_selection_source": selected_backend_source,
        "selected_backend_class": selected_backend_class,
        "route_primary_backend": route_primary_backend,
        "route_primary_backend_class": route_primary_backend_class,
        "route_fallback_backend": route_fallback_backend,
        "route_fallback_backend_class": route_fallback_backend_class,
        "route_fanout_backends": route_fanout_backends,
        "route_fanout_backend_classes": route_fanout_backend_classes,
        "selected_backend_policy": selected_backend_policy,
        "route_primary_backend_policy": route_primary_backend_policy,
        "route_fallback_backend_policy": route_fallback_backend_policy,
        "route_fanout_backend_policies": route_fanout_backend_policies,
        "selected_execution_class": selected_backend_class,
        "effective_execution_posture": effective_execution_posture,
        "mixed_posture": effective_execution_posture == "hybrid",
    })
}

fn activation_kind_from_dispatch_result_path(path: &str) -> Option<&'static str> {
    let result = crate::read_json_file_if_present(Path::new(path))?;
    dispatch_result_activation_kind(&result)
}

fn dispatch_result_activation_kind(result: &serde_json::Value) -> Option<&'static str> {
    if result["activation_vs_execution_evidence"]["evidence_state"].as_str()
        == Some("activation_view_only")
        || result["activation_semantics"]["view_only"].as_bool() == Some(true)
        || result["activation_semantics"]["activation_kind"].as_str() == Some("activation_view")
    {
        return Some("activation_view");
    }
    if dispatch_result_has_receipt_backed_evidence(result)
        && (result["execution_state"].as_str() == Some("blocked")
            || dispatch_result_is_rework_or_blocker(result))
    {
        return Some("execution_evidence");
    }
    if result["activation_vs_execution_evidence"]["evidence_state"].as_str()
        == Some("execution_evidence_recorded")
        || result["activation_semantics"]["activation_kind"].as_str() == Some("execution_evidence")
        || result["execution_evidence"]["status"].as_str() == Some("recorded")
        || (result["artifact_kind"].as_str() == Some("host_tool_bridge_result")
            && result["execution_state"].as_str() == Some("executed")
            && dispatch_result_is_pass_completion(result)
            && dispatch_result_receipt_backed(result))
        || result["artifact_kind"].as_str() == Some("runtime_lane_completion_result")
    {
        return Some("execution_evidence");
    }
    if result["artifact_kind"].as_str() == Some("runtime_dispatch_result")
        || matches!(
            result["execution_state"].as_str(),
            Some("blocked" | "executing")
        )
    {
        return Some("activation_view");
    }
    None
}

fn receipt_result_path_has_execution_evidence(path: Option<&str>) -> bool {
    path.map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(activation_kind_from_dispatch_result_path)
        == Some("execution_evidence")
}

fn receipt_result_path_has_target_execution_evidence(path: Option<&str>, target: &str) -> bool {
    let Some(result) = path
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(crate::runtime_dispatch_result_evidence::read_bounded_dispatch_evidence_json)
    else {
        return false;
    };

    dispatch_result_activation_kind(&result) == Some("execution_evidence")
        && result["completed_target"].as_str() == Some(target)
}

fn receipt_result_path_activation_kind(path: Option<&str>) -> Option<&'static str> {
    path.map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(activation_kind_from_dispatch_result_path)
}

fn receipt_backed_trace_path_for_preview(
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    previous_trace_path: Option<String>,
) -> Option<String> {
    let previous_trace_path = previous_trace_path
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    previous_trace_path.filter(|_| {
        receipt_result_path_activation_kind(receipt.dispatch_result_path.as_deref())
            == Some("execution_evidence")
    })
}

fn canonical_activation_view_only_blocker_code(
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    result: &serde_json::Value,
) -> String {
    json_string(result.get("blocker_code"))
        .or_else(|| receipt.blocker_code.clone())
        .unwrap_or_else(|| "internal_activation_view_only".to_string())
}

pub(crate) fn normalize_activation_view_only_receipt_truth(
    receipt: &mut crate::state_store::RunGraphDispatchReceipt,
) -> Result<bool, String> {
    if !matches!(
        receipt.dispatch_status.as_str(),
        "executed" | "packet_ready" | "executing"
    ) {
        return Ok(false);
    }
    let Some(result_path) = receipt
        .dispatch_result_path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(false);
    };
    let Some(result) = crate::read_json_file_if_present(std::path::Path::new(result_path)) else {
        return Ok(false);
    };
    if dispatch_result_activation_kind(&result) != Some("activation_view") {
        return Ok(false);
    }
    if receipt.dispatch_status == "executing"
        && result["execution_state"].as_str() == Some("executing")
    {
        return Ok(false);
    }

    receipt.dispatch_status = "blocked".to_string();
    receipt.lane_status = derive_lane_status(
        &receipt.dispatch_status,
        receipt.supersedes_receipt_id.as_deref(),
        receipt.exception_path_receipt_id.as_deref(),
    )
    .as_str()
    .to_string();
    receipt.blocker_code = Some(canonical_activation_view_only_blocker_code(
        receipt, &result,
    ));
    receipt.downstream_dispatch_target = None;
    receipt.downstream_dispatch_command = None;
    receipt.downstream_dispatch_note = None;
    receipt.downstream_dispatch_ready = false;
    receipt.downstream_dispatch_blockers.clear();
    receipt.downstream_dispatch_packet_path = None;
    receipt.downstream_dispatch_status = None;
    receipt.downstream_dispatch_result_path = None;
    receipt.downstream_dispatch_trace_path = None;
    receipt.downstream_dispatch_executed_count = 0;
    receipt.downstream_dispatch_active_target = Some(receipt.dispatch_target.clone());
    receipt.downstream_dispatch_last_target = Some(receipt.dispatch_target.clone());
    Ok(true)
}

fn resolve_project_artifact_path(
    project_root: &Path,
    raw_path: Option<&str>,
) -> Option<std::path::PathBuf> {
    let raw_path = raw_path.map(str::trim).filter(|value| !value.is_empty())?;
    let path = Path::new(raw_path);
    Some(if path.is_absolute() {
        path.to_path_buf()
    } else {
        project_root.join(path)
    })
}

pub(crate) fn dispatch_activation_evidence_summary(
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> serde_json::Value {
    let dispatch_result_path = nonempty_result_path(receipt.dispatch_result_path.as_deref());
    let downstream_result_path =
        nonempty_result_path(receipt.downstream_dispatch_result_path.as_deref());
    let evidence_path = dispatch_result_path
        .as_deref()
        .and_then(activation_kind_from_dispatch_result_path)
        .filter(|kind| *kind == "execution_evidence")
        .map(|_| {
            dispatch_result_path
                .clone()
                .expect("dispatch_result_path should exist")
        })
        .or_else(|| {
            downstream_result_path
                .as_deref()
                .and_then(activation_kind_from_dispatch_result_path)
                .filter(|kind| *kind == "execution_evidence")
                .map(|_| {
                    downstream_result_path
                        .clone()
                        .expect("downstream_result_path should exist")
                })
        });
    let activation_kind = if evidence_path.is_some() {
        "execution_evidence"
    } else {
        "activation_view"
    };
    let result_body = evidence_path
        .as_deref()
        .and_then(|path| crate::read_json_file_if_present(Path::new(path)));
    let activation_semantics = result_body
        .as_ref()
        .and_then(|value| value.get("activation_semantics"))
        .cloned()
        .unwrap_or_else(|| {
            serde_json::json!({
                "activation_kind": activation_kind,
                "view_only": activation_kind != "execution_evidence",
                "executes_packet": activation_kind == "execution_evidence",
                "records_completion_receipt": activation_kind == "execution_evidence",
            })
        });
    let execution_evidence = result_body
        .as_ref()
        .and_then(|value| value.get("execution_evidence"))
        .cloned()
        .unwrap_or_else(|| {
            if activation_kind == "execution_evidence" {
                serde_json::json!({
                    "status": "recorded",
                    "receipt_backed": true,
                    "result_path": evidence_path.clone(),
                })
            } else {
                serde_json::Value::Null
            }
        });

    serde_json::json!({
        "activation_kind": activation_kind,
        "evidence_state": if activation_kind == "execution_evidence" {
            "execution_evidence_recorded"
        } else {
            "activation_view_only"
        },
        "execution_evidence_path": evidence_path,
        "receipt_backed": activation_kind == "execution_evidence",
        "activation_semantics": activation_semantics,
        "execution_evidence": execution_evidence,
    })
}

fn activation_evidence_from_result_body(result: &serde_json::Value) -> serde_json::Value {
    let activation_kind = result["activation_semantics"]["activation_kind"]
        .as_str()
        .or_else(|| {
            if result["execution_evidence"]["status"].as_str() == Some("recorded")
                || result["execution_state"].as_str() == Some("executed")
            {
                Some("execution_evidence")
            } else if result["artifact_kind"].as_str() == Some("runtime_dispatch_result")
                || result["execution_state"].as_str() == Some("blocked")
            {
                Some("activation_view")
            } else {
                None
            }
        })
        .unwrap_or("activation_view");
    serde_json::json!({
        "activation_kind": activation_kind,
        "evidence_state": if activation_kind == "execution_evidence" {
            "execution_evidence_recorded"
        } else {
            "activation_view_only"
        },
        "activation_semantics": result["activation_semantics"].clone(),
        "execution_evidence": result["execution_evidence"].clone(),
        "receipt_backed": activation_kind == "execution_evidence",
    })
}

fn activation_evidence_from_receipt_result_paths(
    project_root: &Path,
    dispatch_receipt: &crate::state_store::RunGraphDispatchReceiptSummary,
) -> Option<serde_json::Value> {
    for raw_path in [
        dispatch_receipt.dispatch_result_path.as_deref(),
        dispatch_receipt.downstream_dispatch_result_path.as_deref(),
    ] {
        let Some(resolved) = resolve_project_artifact_path(project_root, raw_path) else {
            continue;
        };
        let Some(result) = crate::read_json_file_if_present(&resolved) else {
            continue;
        };
        return Some(activation_evidence_from_result_body(&result));
    }
    None
}

pub(crate) fn dispatch_surface_truth_from_packet_path(
    project_root: &Path,
    packet_path: Option<&str>,
    dispatch_receipt: &crate::state_store::RunGraphDispatchReceiptSummary,
) -> Option<serde_json::Value> {
    let packet_path = resolve_project_artifact_path(project_root, packet_path)?;
    let packet = crate::read_json_file_if_present(&packet_path)?;
    let mut mixed_posture = packet
        .get("mixed_posture")
        .cloned()
        .or_else(|| packet.get("effective_execution_posture").cloned())
        .or_else(|| packet.get("execution_truth").cloned());
    if let Some(object) = mixed_posture
        .as_mut()
        .and_then(serde_json::Value::as_object_mut)
    {
        if object.get("effective_posture_kind").is_none() {
            if let Some(value) = object
                .get("effective_execution_posture")
                .cloned()
                .or_else(|| object.get("effective_posture_kind").cloned())
            {
                object.insert("effective_posture_kind".to_string(), value);
            }
        }
        if object.get("selected_backend").is_none() {
            if let Some(value) = object
                .get("effective_selected_backend")
                .cloned()
                .or_else(|| object.get("selected_backend").cloned())
            {
                object.insert("selected_backend".to_string(), value);
            }
        }
        if object.get("fanout_backends").is_none() {
            if let Some(value) = object
                .get("fanout_backends")
                .cloned()
                .or_else(|| object.get("fanout_executor_backends").cloned())
            {
                object.insert("fanout_backends".to_string(), value);
            }
        }
        if object.get("fallback_backend").is_none() {
            if let Some(value) = object
                .get("fallback_backend")
                .cloned()
                .or_else(|| object.get("fallback_executor_backend").cloned())
                .or_else(|| object.get("route_fallback_backend").cloned())
            {
                object.insert("fallback_backend".to_string(), value);
            }
        }
    }
    let activation_evidence =
        activation_evidence_from_receipt_result_paths(project_root, dispatch_receipt)
            .or_else(|| packet.get("activation_vs_execution_evidence").cloned())
            .or_else(|| packet.get("activation_evidence").cloned());
    Some(serde_json::json!({
        "mixed_posture": mixed_posture.unwrap_or(serde_json::Value::Null),
        "activation_vs_execution_evidence": activation_evidence.unwrap_or(serde_json::Value::Null),
    }))
}

pub(crate) fn fallback_backend_for_blocked_primary_dispatch_receipt(
    project_root: &std::path::Path,
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    if dispatch_receipt.dispatch_kind != "agent_lane"
        || !dispatch_receipt
            .dispatch_packet_path
            .as_deref()
            .is_some_and(|path| !path.trim().is_empty())
    {
        return None;
    }
    let route = execution_plan_route_for_dispatch_target(
        &role_selection.execution_plan,
        &dispatch_receipt.dispatch_target,
    )?;
    let primary_backend =
        selected_backend_from_execution_plan_route(&role_selection.execution_plan, route)?;
    let fallback_backend = fallback_executor_backend_from_route(route)?;
    if primary_backend == fallback_backend {
        return None;
    }
    let selected_backend = canonical_selected_backend_for_receipt(role_selection, dispatch_receipt)
        .or_else(|| dispatch_receipt.selected_backend.clone())?;
    if selected_backend != primary_backend {
        return None;
    }
    let overlay = load_project_overlay_yaml_for_root(project_root).ok()?;
    let (selected_cli_system, selected_cli_entry) =
        selected_host_cli_system_for_runtime_dispatch(&overlay);
    let preflight = crate::status_surface_external_cli::external_cli_preflight_summary(
        &overlay,
        &selected_cli_system,
        selected_cli_entry.as_ref(),
    );
    let carrier_blocked = preflight["carrier_readiness"]["carriers"]
        .as_array()
        .into_iter()
        .flatten()
        .any(|carrier| {
            carrier["backend_id"].as_str() == Some(primary_backend.as_str())
                && carrier["blocked"].as_bool() == Some(true)
        });
    let previous_primary_result_blocked =
        dispatch_result_blocks_primary_backend(dispatch_receipt, &primary_backend);
    (carrier_blocked || previous_primary_result_blocked).then_some(fallback_backend)
}

fn dispatch_result_blocks_primary_backend(
    dispatch_receipt: &crate::state_store::RunGraphDispatchReceipt,
    primary_backend: &str,
) -> bool {
    let Some(result_path) = dispatch_receipt
        .dispatch_result_path
        .as_deref()
        .map(str::trim)
        .filter(|path| !path.is_empty())
    else {
        return false;
    };
    let Ok(contents) = std::fs::read_to_string(result_path) else {
        return false;
    };
    let Ok(result) = serde_json::from_str::<serde_json::Value>(&contents) else {
        return false;
    };
    let selected_backend = result["selected_backend"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or(dispatch_receipt.selected_backend.as_deref())
        .unwrap_or_default();
    if selected_backend != primary_backend {
        return false;
    }
    let status_blocked = result["status"].as_str().map(str::trim) == Some("blocked");
    let blocker_present = result["blocker_code"]
        .as_str()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty());
    status_blocked && blocker_present
}

pub(crate) fn build_downstream_dispatch_receipt(
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<crate::state_store::RunGraphDispatchReceipt> {
    let raw_dispatch_target = receipt.downstream_dispatch_target.clone()?;
    let authority = require_persisted_team_flow_authority_for_selection(role_selection).ok()?;
    let canonical_dispatch_target = resolve_team_flow_target_for_selection(
        &authority,
        Some(&role_selection.execution_plan),
        &raw_dispatch_target,
    )
    .ok()?
    .dispatch_target;
    let dispatch_target = raw_dispatch_target;
    let recorded_at = time::OffsetDateTime::now_utc()
        .format(&Rfc3339)
        .expect("rfc3339 timestamp should render");
    let (dispatch_kind, dispatch_surface, activation_agent_type, activation_runtime_role) =
        downstream_activation_fields(role_selection, &canonical_dispatch_target);
    let selected_backend = downstream_selected_backend(
        role_selection,
        &dispatch_target,
        activation_agent_type.as_deref(),
        receipt.selected_backend.as_deref(),
    )
    .filter(|value| !value.is_empty());
    let downstream_dispatch_blockers = if selected_backend.is_none()
        && dispatch_target_requires_strict_backend_admissibility(
            &role_selection.execution_plan,
            &dispatch_target,
        ) {
        vec!["selected_backend_not_admissible_for_dispatch_target".to_string()]
    } else {
        Vec::new()
    };
    let dispatch_status = if receipt.downstream_dispatch_ready {
        "routed".to_string()
    } else {
        "blocked".to_string()
    };
    // Downstream lanes must derive their truth from their own receipt state rather than
    // inheriting exception/supersession evidence that belongs to the upstream lane.
    let supersedes_receipt_id = None;
    let exception_path_receipt_id = None;
    Some(crate::state_store::RunGraphDispatchReceipt {
        run_id: receipt.run_id.clone(),
        dispatch_target: dispatch_target.clone(),
        dispatch_status: dispatch_status.clone(),
        supersedes_receipt_id: supersedes_receipt_id.clone(),
        exception_path_receipt_id: exception_path_receipt_id.clone(),
        lane_status: derive_lane_status(
            &dispatch_status,
            supersedes_receipt_id.as_deref(),
            exception_path_receipt_id.as_deref(),
        )
        .as_str()
        .to_string(),
        dispatch_kind,
        dispatch_surface,
        dispatch_command: receipt.downstream_dispatch_command.clone(),
        dispatch_packet_path: receipt.downstream_dispatch_packet_path.clone(),
        dispatch_result_path: None,
        blocker_code: if dispatch_status == "blocked" && receipt.dispatch_status != "executed" {
            blocker_code_value(BlockerCode::MissingLaneReceipt)
        } else if dispatch_status == "blocked" && receipt.downstream_dispatch_packet_path.is_none()
        {
            blocker_code_value(BlockerCode::MissingPacket)
        } else {
            None
        },
        downstream_dispatch_target: None,
        downstream_dispatch_command: None,
        downstream_dispatch_note: None,
        downstream_dispatch_ready: false,
        downstream_dispatch_blockers,
        downstream_dispatch_packet_path: None,
        downstream_dispatch_status: None,
        downstream_dispatch_result_path: None,
        downstream_dispatch_trace_path: None,
        downstream_dispatch_executed_count: 0,
        downstream_dispatch_active_target: None,
        downstream_dispatch_last_target: receipt.downstream_dispatch_last_target.clone(),
        activation_agent_type,
        activation_runtime_role,
        selected_backend,
        policy_bundle_ref: receipt.policy_bundle_ref.clone(),
        recorded_at,
    })
}

fn root_receipt_fields_from_downstream_step(
    root_receipt: &mut crate::state_store::RunGraphDispatchReceipt,
    step_receipt: &crate::state_store::RunGraphDispatchReceipt,
) {
    root_receipt.downstream_dispatch_target = step_receipt.downstream_dispatch_target.clone();
    root_receipt.downstream_dispatch_command = step_receipt.downstream_dispatch_command.clone();
    root_receipt.downstream_dispatch_note = step_receipt.downstream_dispatch_note.clone();
    root_receipt.downstream_dispatch_ready = step_receipt.downstream_dispatch_ready;
    root_receipt.downstream_dispatch_blockers = step_receipt.downstream_dispatch_blockers.clone();
    root_receipt.downstream_dispatch_packet_path =
        step_receipt.downstream_dispatch_packet_path.clone();
    root_receipt.downstream_dispatch_status = step_receipt.downstream_dispatch_status.clone();
    root_receipt.downstream_dispatch_result_path =
        step_receipt.downstream_dispatch_result_path.clone();
    root_receipt.downstream_dispatch_active_target =
        step_receipt.downstream_dispatch_active_target.clone();
    root_receipt.supersedes_receipt_id = if same_evidence_id(
        root_receipt.supersedes_receipt_id.as_deref(),
        step_receipt.supersedes_receipt_id.as_deref(),
    ) {
        None
    } else {
        step_receipt.supersedes_receipt_id.clone()
    };
    root_receipt.exception_path_receipt_id = if same_evidence_id(
        root_receipt.exception_path_receipt_id.as_deref(),
        step_receipt.exception_path_receipt_id.as_deref(),
    ) {
        None
    } else {
        step_receipt.exception_path_receipt_id.clone()
    };
    root_receipt.blocker_code = step_receipt.blocker_code.clone();
}

fn same_evidence_id(lhs: Option<&str>, rhs: Option<&str>) -> bool {
    let lhs = lhs.map(str::trim).filter(|value| !value.is_empty());
    let rhs = rhs.map(str::trim).filter(|value| !value.is_empty());
    lhs.is_some() && lhs == rhs
}

pub(crate) fn active_downstream_dispatch_target(
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    if receipt.dispatch_kind == "agent_lane" && receipt.dispatch_status != "executed" {
        Some(receipt.dispatch_target.clone())
    } else {
        None
    }
}

fn agent_init_packet_flag_for_path(packet_path: &str) -> &'static str {
    if packet_path.contains("/downstream-dispatch-packets/")
        || packet_path.contains("downstream-dispatch-packets")
    {
        "--downstream-packet"
    } else {
        "--dispatch-packet"
    }
}

pub(crate) fn agent_init_command_for_packet_path(packet_path: &str) -> String {
    format!(
        "vida agent-init {} {} --json",
        agent_init_packet_flag_for_path(packet_path),
        shell_quote(packet_path)
    )
}

pub(crate) fn agent_init_execute_command_for_packet_path(packet_path: &str) -> String {
    format!(
        "vida agent-init {} {} --execute-dispatch --json",
        agent_init_packet_flag_for_path(packet_path),
        shell_quote(packet_path)
    )
}

