fn receipt_waiting_on_implementer_evidence(
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> bool {
    receipt.downstream_dispatch_last_target.as_deref() == Some("implementer")
        && receipt.downstream_dispatch_target.as_deref() == Some("coach")
        && !receipt.downstream_dispatch_ready
        && receipt
            .downstream_dispatch_blockers
            .iter()
            .any(|value| value == blocker_code_str(BlockerCode::PendingImplementationEvidence))
}

fn tracked_spec_first_dev_handoff_evidence_path(
    store: &StateStore,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    gate: &crate::state_store::SpecFirstDevHandoffGate,
) -> Result<String, String> {
    let Some(packet_path) = receipt.dispatch_packet_path.as_deref() else {
        return Err(
            "Cannot record spec-first dev handoff evidence without a dispatch packet path"
                .to_string(),
        );
    };
    write_runtime_lane_completion_result_with_summary(
        store.root(),
        &receipt.run_id,
        &receipt.dispatch_target,
        &format!("taskflow-dev-ready-{}", gate.dev_task_id),
        packet_path,
        Some(&format!(
            "TaskFlow child state proves dev-ready handoff: feature={}, spec={}, work_pool={}, dev={}",
            gate.feature_id, gate.spec_task_id, gate.work_pool_task_id, gate.dev_task_id
        )),
    )
}

pub(crate) fn receipt_waiting_on_specification_evidence(
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> bool {
    let specification_gate_blockers = [
        blocker_code_str(BlockerCode::PendingSpecificationEvidence),
        blocker_code_str(BlockerCode::PendingDesignFinalize),
        blocker_code_str(BlockerCode::PendingSpecTaskClose),
    ];
    receipt.dispatch_target == "specification"
        && receipt.downstream_dispatch_target.as_deref() == Some("work-pool-pack")
        && !receipt.downstream_dispatch_ready
        && receipt.downstream_dispatch_blockers.iter().any(|value| {
            specification_gate_blockers
                .iter()
                .any(|blocker| value == blocker)
        })
}

pub(crate) async fn try_bridge_bounded_specification_completion_to_downstream_receipt(
    store: &StateStore,
    role_selection: &RuntimeConsumptionLaneSelection,
    run_graph_bootstrap: &serde_json::Value,
    receipt: &mut crate::state_store::RunGraphDispatchReceipt,
) -> Result<bool, String> {
    let taskflow_dev_ready = spec_first_dev_handoff_gate_from_taskflow(store, receipt).await;
    if !receipt_waiting_on_specification_evidence(receipt) && taskflow_dev_ready.is_none() {
        return Ok(false);
    }

    let result_path = if let Some(gate) = taskflow_dev_ready.as_ref() {
        tracked_spec_first_dev_handoff_evidence_path(store, receipt, gate)?
    } else {
        let Some(result_path) =
            tracked_specification_gate_completion_evidence_path(store, role_selection, receipt)
                .await?
        else {
            return Ok(false);
        };
        result_path
    };

    receipt.dispatch_status = "executed".to_string();
    receipt.lane_status = derive_lane_status(
        &receipt.dispatch_status,
        receipt.supersedes_receipt_id.as_deref(),
        receipt.exception_path_receipt_id.as_deref(),
    )
    .as_str()
    .to_string();
    receipt.dispatch_result_path = Some(result_path);
    receipt.blocker_code = None;
    if receipt.dispatch_target == "specification" {
        receipt.downstream_dispatch_target = None;
        receipt.downstream_dispatch_command = None;
        receipt.downstream_dispatch_note = None;
        receipt.downstream_dispatch_ready = false;
        receipt.downstream_dispatch_blockers.clear();
    }

    let (next_target, next_command, next_note, next_ready, next_blockers) =
        derive_downstream_dispatch_preview(store, role_selection, receipt).await;
    if let Some(error) = downstream_dispatch_ready_blocker_parity_error(next_ready, &next_blockers)
    {
        return Err(error);
    }
    if !next_ready {
        return Ok(false);
    }

    let preview_result_path =
        receipt_backed_execution_evidence_path(store, role_selection, receipt)
            .await
            .map_err(|error| format!("receipt_evidence:{error}"))?;
    apply_downstream_dispatch_preview_to_receipt(
        receipt,
        next_target,
        next_command,
        next_note,
        next_ready,
        next_blockers,
        preview_result_path,
    );
    receipt.downstream_dispatch_trace_path = None;
    let dev_owned_paths = if let Some(gate) = taskflow_dev_ready.as_ref() {
        store
            .list_tasks(None, true)
            .await
            .ok()
            .and_then(|tasks| {
                tasks
                    .into_iter()
                    .find(|task| task.id == gate.dev_task_id)
                    .map(|task| task.planner_metadata.owned_paths)
            })
            .unwrap_or_default()
    } else {
        Vec::new()
    };
    receipt.downstream_dispatch_packet_path =
        write_runtime_downstream_dispatch_packet_with_owned_paths(
            store.root(),
            role_selection,
            run_graph_bootstrap,
            receipt,
            &dev_owned_paths,
        )?;
    if let Some(packet_path) = receipt.downstream_dispatch_packet_path.as_deref() {
        receipt.downstream_dispatch_command =
            Some(agent_init_execute_command_for_packet_path(packet_path));
    }
    receipt.blocker_code = None;
    Ok(true)
}

pub(crate) async fn try_bridge_bounded_implementer_completion_to_downstream_receipt(
    store: &StateStore,
    role_selection: &RuntimeConsumptionLaneSelection,
    run_graph_bootstrap: &serde_json::Value,
    receipt: &mut crate::state_store::RunGraphDispatchReceipt,
) -> Result<bool, String> {
    if !receipt_waiting_on_implementer_evidence(receipt) {
        return Ok(false);
    }

    let Some(implementer_target) = receipt.downstream_dispatch_last_target.clone() else {
        return Ok(false);
    };
    let mut implementer_receipt = receipt.clone();
    // Project only persisted downstream fields into the preview context; do
    // not invent a completion receipt or execution evidence.
    implementer_receipt.dispatch_target = implementer_target;
    implementer_receipt.dispatch_status = receipt
        .downstream_dispatch_status
        .clone()
        .unwrap_or_else(|| receipt.dispatch_status.clone());
    implementer_receipt.dispatch_command = receipt.downstream_dispatch_command.clone();
    implementer_receipt.dispatch_packet_path = receipt.downstream_dispatch_packet_path.clone();
    implementer_receipt.dispatch_result_path = receipt.downstream_dispatch_result_path.clone();
    implementer_receipt.downstream_dispatch_target = None;
    implementer_receipt.downstream_dispatch_command = None;
    implementer_receipt.downstream_dispatch_note = None;
    implementer_receipt.downstream_dispatch_ready = false;
    implementer_receipt.downstream_dispatch_blockers.clear();
    implementer_receipt.downstream_dispatch_packet_path = None;
    implementer_receipt.downstream_dispatch_status = None;
    implementer_receipt.downstream_dispatch_result_path = None;
    implementer_receipt.downstream_dispatch_trace_path = None;
    implementer_receipt.downstream_dispatch_active_target = None;
    implementer_receipt.downstream_dispatch_last_target = None;
    let (next_target, next_command, next_note, next_ready, next_blockers) =
        derive_downstream_dispatch_preview(store, role_selection, &implementer_receipt).await;
    if let Some(error) = downstream_dispatch_ready_blocker_parity_error(next_ready, &next_blockers)
    {
        return Err(error);
    }
    if !next_ready {
        return Ok(false);
    }

    let preview_result_path =
        receipt_backed_execution_evidence_path(store, role_selection, receipt).await?;
    apply_downstream_dispatch_preview_to_receipt(
        receipt,
        next_target,
        next_command,
        next_note,
        next_ready,
        next_blockers,
        preview_result_path,
    );
    receipt.downstream_dispatch_trace_path = None;
    receipt.downstream_dispatch_packet_path = write_runtime_downstream_dispatch_packet(
        store.root(),
        role_selection,
        run_graph_bootstrap,
        receipt,
    )?;
    receipt.blocker_code = None;
    Ok(true)
}

fn receipt_backed_downstream_preview_result_path(
    preview_result_path: Option<String>,
) -> Option<String> {
    preview_result_path
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn apply_downstream_dispatch_preview_to_receipt(
    receipt: &mut crate::state_store::RunGraphDispatchReceipt,
    downstream_dispatch_target: Option<String>,
    downstream_dispatch_command: Option<String>,
    downstream_dispatch_note: Option<String>,
    downstream_dispatch_ready: bool,
    downstream_dispatch_blockers: Vec<String>,
    preview_result_path: Option<String>,
) {
    let preview_result_path = receipt_backed_downstream_preview_result_path(preview_result_path);
    let packet_ready = downstream_dispatch_ready
        && downstream_dispatch_blockers.is_empty()
        && preview_result_path.is_some();
    receipt.downstream_dispatch_target = downstream_dispatch_target;
    receipt.downstream_dispatch_command = downstream_dispatch_command;
    receipt.downstream_dispatch_note = downstream_dispatch_note;
    receipt.downstream_dispatch_ready = downstream_dispatch_ready;
    receipt.downstream_dispatch_blockers = downstream_dispatch_blockers;
    receipt.downstream_dispatch_status = packet_ready.then(|| "packet_ready".to_string());
    receipt.downstream_dispatch_result_path = preview_result_path;
    receipt.downstream_dispatch_active_target = active_downstream_dispatch_target(receipt);
}

async fn spec_first_work_pool_handoff_feature_from_taskflow(
    store: &StateStore,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Option<String> {
    let tasks = store.list_tasks(None, true).await.ok()?;
    let identity = store
        .run_graph_dispatch_task_identity(&receipt.run_id)
        .await
        .ok()
        .flatten();
    let mut candidates = Vec::new();
    if let Some(identity) = identity.as_ref() {
        candidates.extend(
            [
                identity.feature_epic_id.as_deref(),
                identity.spec_task_id.as_deref(),
                identity.work_pool_task_id.as_deref(),
            ]
            .into_iter()
            .flatten()
            .map(str::to_string),
        );
    }
    candidates.push(receipt.run_id.clone());

    let mut visited = BTreeSet::new();
    candidates
        .into_iter()
        .filter(|candidate| visited.insert(candidate.clone()))
        .find_map(|candidate| {
            StateStore::spec_first_work_pool_handoff_gate_satisfied_for_task(&tasks, &candidate)
        })
}

