fn write_runtime_downstream_dispatch_trace(
    state_root: &Path,
    run_id: &str,
    trace: &[serde_json::Value],
) -> Result<String, String> {
    let trace_dir = state_root
        .join("runtime-consumption")
        .join("downstream-dispatch-traces");
    std::fs::create_dir_all(&trace_dir).map_err(|error| {
        format!("Failed to create downstream-dispatch-traces directory: {error}")
    })?;
    let ts = time::OffsetDateTime::now_utc()
        .format(&Rfc3339)
        .expect("rfc3339 timestamp should render")
        .replace(':', "-");
    let trace_path = trace_dir.join(format!("{run_id}-{ts}.json"));
    let body = serde_json::json!({
        "artifact_kind": "runtime_downstream_dispatch_trace",
        "run_id": run_id,
        "recorded_at": time::OffsetDateTime::now_utc()
            .format(&Rfc3339)
            .expect("rfc3339 timestamp should render"),
        "step_count": trace.len(),
        "steps": trace,
    });
    let encoded = serde_json::to_string_pretty(&body)
        .map_err(|error| format!("Failed to encode downstream dispatch trace: {error}"))?;
    std::fs::write(&trace_path, encoded)
        .map_err(|error| format!("Failed to write downstream dispatch trace: {error}"))?;
    Ok(trace_path.display().to_string())
}

pub(crate) fn runtime_dispatch_command_for_target(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
) -> Option<String> {
    match dispatch_target {
        "spec-pack" => json_string(
            role_selection.execution_plan["tracked_flow_bootstrap"].get("bootstrap_command"),
        ),
        "work-pool-pack" => json_string(
            role_selection.execution_plan["tracked_flow_bootstrap"]["work_pool_task"]
                .get("ensure_command"),
        ),
        "dev-pack" => json_string(
            role_selection.execution_plan["tracked_flow_bootstrap"]["dev_task"]
                .get("ensure_command"),
        ),
        _ => typed_team_flow_command_for_dispatch_target(role_selection, dispatch_target),
    }
}

pub(crate) fn runtime_dispatch_packet_kind(
    execution_plan: &serde_json::Value,
    dispatch_target: &str,
    dispatch_kind: &str,
) -> String {
    if dispatch_kind == "taskflow_pack" {
        return "tracked_flow_packet".to_string();
    }
    let requested_dispatch_target = dispatch_target.trim();
    let policy_dispatch_target =
        policy_dispatch_target_for_admissibility(execution_plan, requested_dispatch_target);
    for target in [requested_dispatch_target, policy_dispatch_target.as_str()] {
        if let Some(packet_template_kind) =
            execution_plan_route_for_dispatch_target(execution_plan, target)
                .and_then(|lane| json_string(lane.get("packet_template_kind")))
                .filter(|value| !value.is_empty())
        {
            return packet_template_kind;
        }
    }
    execution_plan_route_for_dispatch_target(execution_plan, &policy_dispatch_target)
        .and_then(|lane| json_string(lane.get("packet_template_kind")))
        .filter(|value| !value.is_empty())
        .unwrap_or_default()
}

pub(crate) fn runtime_dispatch_packet_kind_for_role_selection(
    role_selection: &RuntimeConsumptionLaneSelection,
    dispatch_target: &str,
    dispatch_kind: &str,
) -> Result<String, String> {
    if dispatch_kind == "taskflow_pack" {
        return Ok("tracked_flow_packet".to_string());
    }
    let authority_error =
        match strict_team_flow_node_for_role_selection(role_selection, dispatch_target) {
            Ok(node) => {
                let packet_template_kind = node.packet_template_kind.trim();
                if !packet_template_kind.is_empty() {
                    return Ok(packet_template_kind.to_string());
                }
                Some(format!(
                    "team_flow_packet_template_kind_missing:{dispatch_target}"
                ))
            }
            Err(error) => Some(error),
        };
    let packet_template_kind = runtime_dispatch_packet_kind(
        &role_selection.execution_plan,
        dispatch_target,
        dispatch_kind,
    );
    if !packet_template_kind.trim().is_empty() {
        return Ok(packet_template_kind);
    }
    Err(authority_error
        .unwrap_or_else(|| format!("team_flow_packet_template_kind_missing:{dispatch_target}")))
}

fn strict_team_flow_outcome(value: &str) -> Option<&'static str> {
    match value.trim().to_ascii_lowercase().as_str() {
        "pass" | "completed" | "approve" | "approved" => Some("pass"),
        "rework" | "rework_required" | "blocked" | "blocker" => Some("rework"),
        _ => None,
    }
}

fn strict_team_flow_receipt_from_result(
    result: &Value,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    node_id: &str,
    config_hash: &str,
    snapshot_ref: &str,
) -> Option<TeamFlowReceipt> {
    let mut outcome = None;
    for field in [
        "status",
        "decision",
        "verdict",
        "completion_verdict",
        "outcome",
    ] {
        if let Some(value) = result[field].as_str() {
            let value = strict_team_flow_outcome(value)?;
            if outcome.is_some_and(|current| current != value) {
                return None;
            }
            outcome = Some(value);
        }
    }
    let outcome = outcome?;
    let expected_state = match outcome {
        "pass" => "executed",
        _ => "blocked",
    };
    if result["execution_state"].as_str() != Some(expected_state)
        || receipt.dispatch_status != expected_state
        || !matches!(
            (result["artifact_kind"].as_str(), outcome),
            (Some("host_tool_bridge_result"), _)
                | (Some("runtime_lane_completion_result"), "pass")
                | (Some("runtime_dispatch_result"), "rework")
        )
        || result["run_id"].as_str() != Some(receipt.run_id.as_str())
        || result["activation_semantics"]["activation_kind"].as_str() != Some("execution_evidence")
        || result["activation_semantics"]["view_only"].as_bool() != Some(false)
        || result["activation_semantics"]["executes_packet"].as_bool() != Some(true)
        || result["activation_semantics"]["records_completion_receipt"].as_bool()
            != Some(outcome == "pass")
        || result["execution_evidence"]["receipt_backed"].as_bool() != Some(true)
        || !dispatch_result_matches_receipt_target(result, receipt)
        || !dispatch_result_matches_receipt_source_packet(result, receipt)
    {
        return None;
    }
    let typed =
        serde_json::from_value::<TeamFlowReceipt>(result["team_flow_receipt"].clone()).ok()?;
    let outer_id = result["completion_receipt_id"].as_str()?;
    if outer_id.trim().is_empty()
        || result["execution_evidence"]["receipt_id"].as_str() != Some(outer_id)
        || typed.receipt_id != outer_id
        || typed.node_id != node_id
        || strict_team_flow_outcome(&typed.status)? != outcome
        || typed.config_hash != config_hash
        || typed.snapshot_ref != snapshot_ref
    {
        return None;
    }
    Some(typed)
}

fn strict_state_root_json(state_root: &Path, path: &str) -> Option<Value> {
    let root = std::fs::canonicalize(state_root).ok()?;
    let candidate = std::fs::canonicalize(state_root.join(path)).ok()?;
    if !candidate.starts_with(root) {
        return None;
    }
    serde_json::from_str(&std::fs::read_to_string(candidate).ok()?).ok()
}

fn strict_team_flow_receipt_from_path(
    state_root: &Path,
    path: &str,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    node_id: &str,
    config_hash: &str,
    snapshot_ref: &str,
) -> Option<TeamFlowReceipt> {
    strict_team_flow_receipt_from_result(
        &strict_state_root_json(state_root, path)?,
        receipt,
        node_id,
        config_hash,
        snapshot_ref,
    )
}

fn strict_team_flow_trace_receipt(
    state_root: &Path,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    node_id: &str,
    config_hash: &str,
    snapshot_ref: &str,
) -> Option<TeamFlowReceipt> {
    let authority = require_persisted_team_flow_authority_for_selection(role_selection).ok()?;
    let trace_path = receipt.downstream_dispatch_trace_path.as_deref()?;
    let trace = strict_state_root_json(state_root, trace_path)?;
    if trace["artifact_kind"].as_str() != Some("runtime_downstream_dispatch_trace")
        || trace["run_id"].as_str() != Some(receipt.run_id.as_str())
    {
        return None;
    }
    let steps = trace["steps"].as_array()?;
    let superseded = steps
        .iter()
        .filter_map(|step| step["supersedes_receipt_id"].as_str().map(str::to_string))
        .collect::<BTreeSet<_>>();
    let mut latest = None;
    for step in steps {
        let Ok(step) =
            serde_json::from_value::<crate::state_store::RunGraphDispatchReceipt>(step.clone())
        else {
            continue;
        };
        if step.run_id != receipt.run_id {
            continue;
        }
        let Ok(step_node) = authority.resolve_target(None, &step.dispatch_target) else {
            continue;
        };
        let Some(candidate) = step.dispatch_result_path.as_deref().and_then(|path| {
            strict_team_flow_receipt_from_path(
                state_root,
                path,
                &step,
                &step_node.node_id,
                config_hash,
                snapshot_ref,
            )
        }) else {
            continue;
        };
        if candidate.node_id == node_id && !superseded.contains(&candidate.receipt_id) {
            latest = Some(candidate);
        }
    }
    latest
}

fn typed_team_flow_receipt(
    state_root: &Path,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    node_id: &str,
    config_hash: &str,
    snapshot_ref: &str,
    strict_receipt_required: bool,
) -> Option<TeamFlowReceipt> {
    if strict_receipt_required {
        if receipt.downstream_dispatch_trace_path.is_some() {
            return strict_team_flow_trace_receipt(
                state_root,
                role_selection,
                receipt,
                node_id,
                config_hash,
                snapshot_ref,
            );
        }
        return [
            receipt.downstream_dispatch_result_path.as_deref(),
            receipt.dispatch_result_path.as_deref(),
        ]
        .into_iter()
        .flatten()
        .find_map(|path| {
            strict_team_flow_receipt_from_path(
                state_root,
                path,
                receipt,
                node_id,
                config_hash,
                snapshot_ref,
            )
        });
    }
    [
        receipt.downstream_dispatch_result_path.as_deref(),
        receipt.dispatch_result_path.as_deref(),
    ]
    .into_iter()
    .flatten()
    .filter_map(|path| {
        let result = result_json_from_receipt_path(state_root, Some(path))?;
        if !dispatch_result_matches_receipt_target(&result, receipt) {
            return None;
        }
        let status = [
            "status",
            "decision",
            "verdict",
            "completion_verdict",
            "execution_state",
        ]
        .into_iter()
        .filter_map(|field| json_string(result.get(field)))
        .find(|value| normalize_receipt_outcome(value).is_some())?;
        let mut evidence = Vec::new();
        for field in ["evidence", "evidence_ids", "proof_outputs"] {
            if let Some(values) = result.get(field).and_then(Value::as_array) {
                evidence.extend(values.iter().filter_map(Value::as_str).map(str::to_string));
            }
        }
        Some(TeamFlowReceipt {
            receipt_id: result["receipt_id"]
                .as_str()
                .or_else(|| result["completion_receipt_id"].as_str())
                .unwrap_or("runtime-dispatch-receipt")
                .to_string(),
            node_id: node_id.to_string(),
            status,
            evidence,
            config_hash: config_hash.to_string(),
            snapshot_ref: snapshot_ref.to_string(),
        })
    })
    .next()
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum TypedTeamFlowSuccessor {
    Dispatch(String),
    Closure,
}

fn typed_team_flow_successor_from_receipts(
    state_root: &Path,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> Result<Option<TypedTeamFlowSuccessor>, String> {
    let authority = require_persisted_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    let current = authority
        .resolve_target(None, &receipt.dispatch_target)
        .map_err(|blocker| blocker.code)?;
    if current.evidence_requirements.is_empty() {
        return Ok(None);
    }
    let typed_receipt = typed_team_flow_receipt(
        state_root,
        role_selection,
        receipt,
        &current.node_id,
        &authority.snapshot.config_hash,
        &authority.snapshot.snapshot_ref,
        true,
    )
    .ok_or_else(|| current.completion_blocker.clone())?;
    match strict_team_flow_outcome(&typed_receipt.status) {
        Some("rework") => {
            let [target] = current.rework_targets.as_slice() else {
                return Err("team_flow_rework_target_not_configured".to_string());
            };
            authority
                .admit_rework(&current.node_id, &typed_receipt, target)
                .map_err(|blocker| blocker.code)?;
            Ok(Some(TypedTeamFlowSuccessor::Dispatch(target.clone())))
        }
        Some("pass") if !current.terminal => {
            let target = current
                .next_node
                .as_deref()
                .ok_or_else(|| "team_flow_invalid_requested_node".to_string())?;
            authority
                .admit_next(&current.node_id, &typed_receipt, target)
                .map_err(|blocker| blocker.code)?;
            Ok(Some(TypedTeamFlowSuccessor::Dispatch(target.to_string())))
        }
        Some("pass") => {
            for node in authority
                .ordered_nodes()
                .filter(|node| node.node.included && node.node.required)
            {
                let admitted = typed_team_flow_receipt(
                    state_root,
                    role_selection,
                    receipt,
                    &node.node.node_id,
                    &authority.snapshot.config_hash,
                    &authority.snapshot.snapshot_ref,
                    true,
                )
                .ok_or_else(|| node.completion_blocker.clone())?;
                if strict_team_flow_outcome(&admitted.status) != Some("pass") {
                    return Err(node.completion_blocker.clone());
                }
                if node.node.terminal {
                    authority
                        .admit_terminal(&node.node.node_id, &admitted)
                        .map_err(|blocker| blocker.code)?;
                } else {
                    let target = node
                        .node
                        .next_node
                        .as_deref()
                        .ok_or_else(|| "team_flow_invalid_requested_node".to_string())?;
                    authority
                        .admit_next(&node.node.node_id, &admitted, target)
                        .map_err(|blocker| blocker.code)?;
                }
            }
            Ok(Some(TypedTeamFlowSuccessor::Closure))
        }
        _ => Err(current.completion_blocker),
    }
}

fn typed_team_flow_admission_for_explicit_target(
    state_root: &Path,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    explicit_target: &str,
) -> Option<Result<String, String>> {
    let authority = match require_persisted_team_flow_authority_for_selection(role_selection) {
        Ok(authority) => authority,
        Err(blocker) => return Some(Err(blocker.code)),
    };
    let current = match authority.resolve_target(None, &receipt.dispatch_target) {
        Ok(node) => node,
        Err(blocker) => return Some(Err(blocker.code)),
    };
    let requested = match authority.resolve_target(None, explicit_target) {
        Ok(node) => node,
        Err(blocker) => return Some(Err(blocker.code)),
    };
    let Some(typed_receipt) = typed_team_flow_receipt(
        state_root,
        role_selection,
        receipt,
        &current.node_id,
        &authority.snapshot.config_hash,
        &authority.snapshot.snapshot_ref,
        !current.evidence_requirements.is_empty(),
    ) else {
        return Some(Err("team_flow_transition_receipt_missing".to_string()));
    };
    let verdict = match authority.admit_next(&current.node_id, &typed_receipt, &requested.node_id) {
        Ok(verdict) => verdict,
        Err(blocker) => return Some(Err(blocker.code)),
    };
    if verdict.allowed {
        return Some(Ok(requested.dispatch_target));
    }
    Some(Err(verdict.blocker.unwrap_or_else(|| {
        "team_flow_transition_blocked".to_string()
    })))
}

pub(crate) fn lawful_explicit_rework_dispatch_target_for_role_selection(
    state_root: &Path,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    explicit_target: &str,
    rework_target: &str,
) -> Result<Option<String>, String> {
    let authority = require_persisted_team_flow_authority_for_selection(role_selection)
        .map_err(|blocker| blocker.code)?;
    let current = authority
        .resolve_target(None, &receipt.dispatch_target)
        .map_err(|blocker| blocker.code)?;
    let requested = authority
        .resolve_target(None, explicit_target)
        .map_err(|blocker| blocker.code)?;
    let declared_rework_target = authority
        .resolve_target(None, rework_target)
        .map_err(|blocker| blocker.code)?;
    if declared_rework_target.node_id != requested.node_id {
        return Err("team_flow_rework_target_mismatch".to_string());
    }
    let Some(typed_receipt) = typed_team_flow_receipt(
        state_root,
        role_selection,
        receipt,
        &current.node_id,
        &authority.snapshot.config_hash,
        &authority.snapshot.snapshot_ref,
        !current.evidence_requirements.is_empty(),
    ) else {
        return Err("team_flow_transition_receipt_missing".to_string());
    };
    let verdict = authority
        .admit_rework(&current.node_id, &typed_receipt, &requested.node_id)
        .map_err(|blocker| blocker.code)?;
    if verdict.allowed {
        Ok(Some(requested.dispatch_target))
    } else {
        Err(verdict
            .blocker
            .unwrap_or_else(|| "team_flow_transition_blocked".to_string()))
    }
}
pub(crate) async fn derive_downstream_dispatch_preview(
    store: &StateStore,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> (
    Option<String>,
    Option<String>,
    Option<String>,
    bool,
    Vec<String>,
) {
    let (target, command, note, ready, mut blockers) =
        derive_downstream_dispatch_preview_from_config(store, role_selection, receipt).await;
    if receipt.dispatch_kind == "agent_lane"
        && target
            .as_deref()
            .is_some_and(|value| !matches!(value, "closure"))
        && command.is_none()
    {
        blockers.push("missing_configured_dispatch_command".to_string());
        return (target, command, note, false, blockers);
    }
    (target, command, note, ready, blockers)
}

async fn derive_downstream_dispatch_preview_from_config(
    store: &StateStore,
    role_selection: &RuntimeConsumptionLaneSelection,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
) -> (
    Option<String>,
    Option<String>,
    Option<String>,
    bool,
    Vec<String>,
) {
    let agent_only_development =
        super::execution_plan_agent_only_development_required(&role_selection.execution_plan);
    let lane_sequence = match typed_lane_node_sequence(role_selection, false) {
        Ok(sequence) => sequence,
        Err(blocker) => {
            return (
                None,
                None,
                Some(format!(
                    "typed TeamFlow lane sequence is blocked: {blocker}"
                )),
                false,
                vec![blocker],
            );
        }
    };
    // Executable progression carries stable node ids; dispatch aliases are
    // projected only when emitting a packet/preview target.
    let allowed_next_lane_sequence = lane_sequence
        .iter()
        .map(|node| node.node_id.clone())
        .collect::<Vec<_>>();
    if receipt.dispatch_kind == "agent_lane"
        && matches!(
            receipt.dispatch_status.as_str(),
            "executed" | "pass" | "blocked"
        )
    {
        match typed_team_flow_successor_from_receipts(store.root(), role_selection, receipt) {
            Ok(Some(TypedTeamFlowSuccessor::Dispatch(target))) => {
                let target = match strict_team_flow_node_for_role_selection(role_selection, &target)
                {
                    Ok(target) => target,
                    Err(blocker) => return (None, None, None, false, vec![blocker]),
                };
                let missing_owned_scope = request_missing_owned_write_scope_for_dispatch_target(
                    store,
                    role_selection,
                    receipt,
                    &target.node_id,
                )
                .await;
                return (
                    Some(target.dispatch_target.clone()),
                    typed_team_flow_command_for_dispatch_target(role_selection, &target.node_id),
                    Some(format!(
                        "typed TeamFlow receipt admitted `{}` after `{}` evidence",
                        target.dispatch_target, receipt.dispatch_target
                    )),
                    !missing_owned_scope,
                    if missing_owned_scope {
                        vec![missing_owned_write_scope_blocker()]
                    } else {
                        Vec::new()
                    },
                );
            }
            Ok(Some(TypedTeamFlowSuccessor::Closure)) => {
                return (
                    Some("closure".to_string()),
                    None,
                    Some(format!(
                        "all configured required TeamFlow receipts admit closure after `{}`",
                        receipt.dispatch_target
                    )),
                    true,
                    Vec::new(),
                );
            }
            Ok(None) => {}
            Err(blocker) => {
                return (
                    None,
                    None,
                    Some(format!("typed TeamFlow transition is blocked: {blocker}")),
                    false,
                    vec![blocker],
                );
            }
        }
    }
    if receipt.dispatch_kind == "agent_lane"
        && matches!(receipt.dispatch_status.as_str(), "executed" | "pass")
        && (dispatch_receipt_has_execution_evidence(receipt)
            || dispatch_receipt_allows_synthetic_lane_completion(receipt))
    {
        let terminal_admission = if selected_flow_node_ref(role_selection).is_some() {
            selected_team_flow_node_for_role_selection(role_selection, &receipt.dispatch_target)
                .map(|node| node.is_some_and(|node| node.terminal))
        } else {
            typed_terminal_dispatch_target(role_selection, &receipt.dispatch_target)
        };
        match terminal_admission {
            Ok(true) => {
                return (
                    None,
                    None,
                    Some(format!(
                        "terminal closure `{}` is complete; ignore persisted successor routing",
                        receipt.dispatch_target
                    )),
                    true,
                    Vec::new(),
                );
            }
            Ok(false) => {}
            Err(blocker) => {
                return (
                    None,
                    None,
                    Some(format!(
                        "typed TeamFlow terminal admission is blocked: {blocker}"
                    )),
                    false,
                    vec![blocker],
                );
            }
        }
        if let Some(explicit_target) =
            normalized_explicit_allowed_next_target(receipt.downstream_dispatch_target.as_deref())
                .filter(|target| {
                    !matches!(target.as_str(), "spec-pack" | "work-pool-pack" | "dev-pack")
                })
        {
            if explicit_target == "closure" {
                return (
                    Some("closure".to_string()),
                    None,
                    Some(format!(
                        "explicit allowed_next_node `closure` closes the bounded lane after `{}` evidence",
                        receipt.dispatch_target
                    )),
                    true,
                    Vec::new(),
                );
            }
            if let Some(admission) = typed_team_flow_admission_for_explicit_target(
                store.root(),
                role_selection,
                receipt,
                &explicit_target,
            ) {
                match admission {
                    Ok(target) => {
                        let missing_owned_scope =
                            request_missing_owned_write_scope_for_dispatch_target(
                                store,
                                role_selection,
                                receipt,
                                &target,
                            )
                            .await;
                        let command =
                            typed_team_flow_command_for_dispatch_target(role_selection, &target);
                        return (
                            Some(target.clone()),
                            command,
                            Some(format!(
                                "typed TeamFlow authority admitted configured successor {} after {} evidence",
                                target, receipt.dispatch_target
                            )),
                            !missing_owned_scope,
                            if missing_owned_scope {
                                vec![missing_owned_write_scope_blocker()]
                            } else {
                                Vec::new()
                            },
                        );
                    }
                    Err(blocker) => {
                        return (
                            None,
                            None,
                            Some(format!(
                                "typed TeamFlow authority blocked explicit successor `{explicit_target}`: {blocker}"
                            )),
                            false,
                            vec![blocker],
                        );
                    }
                }
            }
            return (
                None,
                None,
                Some(format!(
                    "explicit allowed_next_node `{}` is not the next lawful lane after `{}` in the execution plan",
                    explicit_target, receipt.dispatch_target
                )),
                false,
                vec![invalid_allowed_next_node_for_execution_plan_blocker()],
            );
        }
    }
    match receipt.dispatch_target.as_str() {
        "spec-pack" if agent_only_development => {
            let selected_node_id = match validated_selected_flow_node_ref(role_selection) {
                Ok(Some(selected_node_id)) => selected_node_id,
                Ok(None) => {
                    return (
                        None,
                        None,
                        Some("spec-pack has no selected TeamFlow execution node".to_string()),
                        false,
                        vec!["team_flow_authority_selected_node_id_missing".to_string()],
                    )
                }
                Err(blocker) => {
                    return (
                        None,
                        None,
                        Some(format!("selected TeamFlow execution node is blocked: {blocker}")),
                        false,
                        vec![blocker],
                    )
                }
            };
            let selected_node = match strict_team_flow_node_for_role_selection(
                role_selection,
                &selected_node_id,
            ) {
                Ok(node) => node,
                Err(blocker) => {
                    return (
                        None,
                        None,
                        Some(format!("selected TeamFlow execution node is blocked: {blocker}")),
                        false,
                        vec![blocker],
                    )
                }
            };
            (
            Some(selected_node.dispatch_target.clone()),
            typed_team_flow_command_for_dispatch_target(role_selection, &selected_node.node_id),
            Some(format!(
                "after spec-pack task materialization, dispatch configured lane `{}` before work-pool shaping",
                selected_node.dispatch_target
            )),
            true,
            Vec::new(),
        )}
        "spec-pack" | "specification" => {
            let taskflow_dev_ready = spec_first_dev_handoff_gate_from_taskflow(store, receipt).await;
            if let Some(gate) = taskflow_dev_ready {
                let Ok(next_target) = first_runtime_dispatch_target_after_dev_pack(role_selection)
                else {
                    return (
                        None,
                        None,
                        Some(
                            "spec-first dev handoff is ready in TaskFlow, but no configured runtime dispatch target could be resolved"
                                .to_string(),
                        ),
                        false,
                        vec!["missing_configured_runtime_dispatch_target".to_string()],
                    );
                };
                return (
                    Some(next_target.dispatch_target.clone()),
                    typed_team_flow_command_for_dispatch_target(role_selection, &next_target.node_id),
                    Some(format!(
                        "spec-first feature `{}` has closed spec/work-pool tasks and open dev task `{}`; dispatch configured runtime target `{}`",
                        gate.feature_id, gate.dev_task_id, next_target.dispatch_target
                    )),
                    true,
                    Vec::new(),
                );
            }
            let taskflow_feature_ready =
                spec_first_work_pool_handoff_feature_from_taskflow(store, receipt).await;
            let design_doc_finalized =
                tracked_design_doc_finalized(role_selection) || taskflow_feature_ready.is_some();
            let spec_task_closed = tracked_specification_task_closed(store, role_selection, receipt)
                .await
                || taskflow_feature_ready.is_some();
            let ready = design_doc_finalized && spec_task_closed;
            let mut blockers = Vec::new();
            if !design_doc_finalized {
                blockers.push(
                    blocker_code_value(BlockerCode::PendingDesignFinalize)
                        .expect("pending design finalize should stay registry-backed"),
                );
            }
            if !spec_task_closed {
                blockers.push(
                    blocker_code_value(BlockerCode::PendingSpecTaskClose)
                        .expect("pending spec task close should stay registry-backed"),
                );
            }
            (
                Some("work-pool-pack".to_string()),
                json_string(
                    role_selection.execution_plan["tracked_flow_bootstrap"]["work_pool_task"]
                        .get("ensure_command"),
                ),
                Some(
                    if let Some(feature_id) = taskflow_feature_ready.as_deref() {
                        format!(
                            "spec-first feature `{feature_id}` has a closed spec-pack task; ensure or reuse the tracked work-pool packet"
                        )
                    } else if ready {
                        "design document is finalized and the spec task is closed; ensure or reuse the tracked work-pool packet".to_string()
                    } else {
                        "after the design document is finalized and the spec task is closed, ensure or reuse the tracked work-pool packet"
                            .to_string()
                    },
                ),
                ready,
                blockers,
            )
        }
        "work-pool-pack" => (
            Some("dev-pack".to_string()),
            json_string(
                role_selection.execution_plan["tracked_flow_bootstrap"]["dev_task"]
                    .get("ensure_command"),
            ),
            Some(
                "after the work-pool packet is shaped, ensure or reuse the bounded dev packet for delegated implementation"
                    .to_string(),
            ),
            receipt.dispatch_status == "executed",
            if receipt.dispatch_status == "executed" {
                Vec::new()
            } else {
                vec!["pending_work_pool_shape".to_string()]
            },
        ),
        "dev-pack" => {
            let Ok(next_target) = first_runtime_dispatch_target_after_dev_pack(role_selection)
            else {
                return (
                    None,
                    None,
                    Some(
                        "dev-pack materialization is complete, but no configured runtime dispatch target could be resolved"
                            .to_string(),
                    ),
                    false,
                    vec!["missing_configured_runtime_dispatch_target".to_string()],
                );
            };
            let missing_owned_scope =
                request_missing_owned_write_scope_for_dispatch_target(
                    store,
                    role_selection,
                    receipt,
                    &next_target.node_id,
                )
                .await;
            let command =
                typed_team_flow_command_for_dispatch_target(role_selection, &next_target.node_id);
            (
                Some(next_target.dispatch_target),
                command,
                Some(
                    "after the dev packet is created, activate the selected implementer lane for bounded execution"
                        .to_string(),
                ),
                !missing_owned_scope,
                if missing_owned_scope {
                    vec![missing_owned_write_scope_blocker()]
                } else {
                    Vec::new()
                },
            )
        }
        "closure" => (
            None,
            None,
            Some("terminal closure is the active bounded runtime target".to_string()),
            false,
            Vec::new(),
        ),
        _ if receipt.dispatch_kind == "agent_lane" => {
            if matches!(
                receipt.dispatch_status.as_str(),
                "routed" | "executing" | "bridge_request_pending"
            ) {
                return (
                    None,
                    typed_team_flow_command_for_dispatch_target(role_selection, &receipt.dispatch_target),
                    Some(format!(
                        "`{}` dispatch is in flight; wait for terminal execution evidence before deriving downstream lane blockers",
                        receipt.dispatch_target
                    )),
                    false,
                    Vec::new(),
                );
            }
            let (current_node, selected_node_authoritative) = match
                selected_team_flow_node_for_role_selection(role_selection, &receipt.dispatch_target)
            {
                Ok(Some(node)) => (node, true),
                Ok(None) => match strict_team_flow_node_for_role_selection(
                    role_selection,
                    &receipt.dispatch_target,
                ) {
                    Ok(node) => (node, false),
                    Err(blocker) => {
                        return (
                            None,
                            None,
                            Some(format!("current typed TeamFlow lane is blocked: {blocker}")),
                            false,
                            vec![blocker],
                        )
                    }
                },
                Err(blocker) => {
                    return (
                        None,
                        None,
                        Some(format!("current typed TeamFlow lane is blocked: {blocker}")),
                        false,
                        vec![blocker],
                    )
                }
            };
            let current_index = match typed_execution_lane_sequence_index_for_target(
                role_selection,
                &allowed_next_lane_sequence,
                &current_node.node_id,
                (!selected_node_authoritative)
                    .then_some(receipt.downstream_dispatch_last_target.as_deref())
                    .flatten(),
            ) {
                Ok(index) => index,
                Err(blocker) => {
                    return (
                        None,
                        None,
                        Some(format!("current typed TeamFlow lane is blocked: {blocker}")),
                        false,
                        vec![blocker],
                    )
                }
            };
            if current_index.is_some_and(|index| allowed_next_lane_sequence.get(index + 1).is_none()) {
                if current_node.stage == "execution"
                    && current_node.closure_class == "implementation"
                {
                    let has_lane_evidence = dispatch_receipt_has_execution_evidence(receipt)
                        || dispatch_receipt_allows_synthetic_lane_completion(receipt)
                        || tracked_implementer_task_closed(store, role_selection, receipt).await;
                    let blocker = (!current_node.completion_blocker.trim().is_empty())
                        .then_some(current_node.completion_blocker.clone())
                        .unwrap_or_else(|| blocker_code_str(BlockerCode::PendingLaneEvidence).to_string());
                    return (
                        Some("closure".to_string()),
                        None,
                        Some(
                            "no additional downstream lane is required by the current execution plan after this handoff"
                                .to_string(),
                        ),
                        has_lane_evidence,
                        if has_lane_evidence {
                            Vec::new()
                        } else {
                            downstream_preview_blockers_for_missing_lane_evidence(receipt, &blocker)
                        },
                    );
                }
            }
            let current_lane = Some(current_node.clone());
            let configured_successor_present =
                current_index.and_then(|index| allowed_next_lane_sequence.get(index + 1)).is_some();
            if current_lane.as_ref().map(|lane| lane.stage.as_str()) == Some("design_gate")
                || (receipt.dispatch_target == "specification"
                    && current_lane.as_ref().map(|lane| lane.stage.as_str()).is_none()
                    && role_selection.tracked_flow_entry.as_deref() == Some("spec-pack"))
            {
                if configured_successor_present {
                    // The configured lane sequence owns multi-agent progression; the
                    // spec/design closure shortcut only applies at a terminal lane.
                } else if !tracked_specification_gate_required(role_selection) {
                    let has_specification_evidence = dispatch_receipt_has_execution_evidence(receipt)
                        || dispatch_receipt_allows_synthetic_lane_completion(receipt);
                    let evidence_blocker = current_lane
                        .as_ref()
                        .map(|lane| lane.completion_blocker.clone())
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| blocker_code_str(BlockerCode::PendingSpecificationEvidence).to_string());
                    return (
                        Some("closure".to_string()),
                        None,
                        Some(
                            "specification evidence is recorded and no tracked design-first gate is required; close the bounded lane"
                                .to_string(),
                        ),
                        has_specification_evidence,
                        if has_specification_evidence {
                            Vec::new()
                        } else {
                            downstream_preview_blockers_for_missing_lane_evidence(
                                receipt,
                                &evidence_blocker,
                            )
                        },
                    );
                } else {
                let has_specification_evidence = dispatch_receipt_has_execution_evidence(receipt)
                    || tracked_specification_gate_completion_ready(store, role_selection, receipt)
                        .await;
                let taskflow_feature_ready =
                    spec_first_work_pool_handoff_feature_from_taskflow(store, receipt).await;
                let taskflow_dev_ready =
                    spec_first_dev_handoff_gate_from_taskflow(store, receipt).await;
                if let Some(gate) = taskflow_dev_ready {
                    let Ok(next_target) = first_runtime_dispatch_target_after_dev_pack(role_selection)
                    else {
                        return (
                            None,
                            None,
                            Some(
                                "spec-first dev handoff is ready in TaskFlow, but no configured runtime dispatch target could be resolved"
                                    .to_string(),
                            ),
                            false,
                            vec!["missing_configured_runtime_dispatch_target".to_string()],
                        );
                    };
                    return (
                        Some(next_target.dispatch_target.clone()),
                        typed_team_flow_command_for_dispatch_target(role_selection, &next_target.node_id),
                        Some(format!(
                            "spec-first feature `{}` has closed spec/work-pool tasks and open dev task `{}`; dispatch configured runtime target `{}`",
                            gate.feature_id, gate.dev_task_id, next_target.dispatch_target
                        )),
                        true,
                        Vec::new(),
                    );
                }
                let spec_task_closed = tracked_specification_task_closed(store, role_selection, receipt)
                    .await
                    || taskflow_feature_ready.is_some();
                let design_doc_finalized =
                    tracked_design_doc_finalized(role_selection) || taskflow_feature_ready.is_some();
                let evidence_blocker = current_lane
                    .as_ref()
                    .map(|lane| lane.completion_blocker.clone())
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or_else(|| blocker_code_str(BlockerCode::PendingSpecificationEvidence).to_string());
                return (
                    Some("work-pool-pack".to_string()),
                    json_string(
                        role_selection.execution_plan["tracked_flow_bootstrap"]["work_pool_task"]
                        .get("ensure_command"),
                    ),
                    Some(
                        if let Some(feature_id) = taskflow_feature_ready.as_deref() {
                            format!(
                                "spec-first feature `{feature_id}` has a closed spec-pack task; ensure or reuse the tracked work-pool packet"
                            )
                        } else if receipt.dispatch_status == "executed"
                            && has_specification_evidence
                            && spec_task_closed
                            && design_doc_finalized
                        {
                            "specification/planning evidence is recorded and the spec-pack is closed; ensure or reuse the tracked work-pool packet".to_string()
                        } else if receipt.dispatch_status == "executed" {
                            "after specification/planning evidence is recorded, finalize the design doc and close spec-pack before work-pool shaping via tracked work-pool ensure/reuse"
                                .to_string()
                        } else {
                            "specification/planning lane is active; wait for bounded evidence return before design finalization, spec-pack closure, and tracked work-pool ensure/reuse"
                                .to_string()
                        }
                    ),
                    has_specification_evidence && spec_task_closed && design_doc_finalized,
                    {
                        let mut blockers = Vec::new();
                        if !has_specification_evidence {
                            blockers.push(evidence_blocker.to_string());
                        }
                        if !spec_task_closed {
                            blockers.push(
                                blocker_code_value(BlockerCode::PendingSpecTaskClose)
                                    .expect("pending spec task close should stay registry-backed"),
                            );
                        }
                        if !design_doc_finalized {
                            blockers.push(
                                blocker_code_value(BlockerCode::PendingDesignFinalize).expect(
                                    "pending design finalize should stay registry-backed",
                                ),
                            );
                        }
                        blockers
                    },
                );
                }
            }
            let implementation = &role_selection.execution_plan["development_flow"]["implementation"];
            let Some(analysis_target) = implementation
                .get("analysis_route_task_class")
                .and_then(serde_json::Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            else {
                return (
                    None,
                    None,
                    Some("implementation analysis route is not configured".to_string()),
                    false,
                    vec!["team_flow_implementation_analysis_route_missing".to_string()],
                );
            };
            if receipt.dispatch_target == analysis_target
                && (dispatch_receipt_has_execution_evidence(receipt)
                    || dispatch_receipt_allows_synthetic_lane_completion(receipt))
            {
                let Some(writer_target) = implementation
                    .get("writer_route_task_class")
                    .or_else(|| implementation.get("implementer_route_task_class"))
                    .and_then(serde_json::Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                else {
                    return (
                        None,
                        None,
                        Some("implementation writer route is not configured".to_string()),
                        false,
                        vec!["team_flow_implementation_writer_route_missing".to_string()],
                    );
                };
                let writer_node = match strict_team_flow_node_for_role_selection(
                    role_selection,
                    writer_target,
                ) {
                    Ok(node) => node,
                    Err(blocker) => {
                        return (
                            None,
                            None,
                            Some(format!("configured writer TeamFlow node is blocked: {blocker}")),
                            false,
                            vec![blocker],
                        )
                    }
                };
                let missing_owned_scope = request_missing_owned_write_scope_for_dispatch_target(
                    store,
                    role_selection,
                    receipt,
                    &writer_node.node_id,
                )
                .await;
                let command =
                    typed_team_flow_command_for_dispatch_target(role_selection, &writer_node.node_id);
                return (
                    Some(writer_node.dispatch_target.clone()),
                    command,
                    Some(format!(
                        "after `{}` validation evidence is recorded, activate `{}` for the first implementation lane",
                        receipt.dispatch_target, writer_node.dispatch_target
                    )),
                    !missing_owned_scope,
                    if missing_owned_scope {
                        vec![missing_owned_write_scope_blocker()]
                    } else {
                        Vec::new()
                    },
                );
            }
            let runtime_role_target_result = if selected_node_authoritative {
                None
            } else {
                receipt
                    .activation_runtime_role
                    .as_deref()
                    .map(|runtime_role| {
                        authority_dispatch_target_for_runtime_role(role_selection, runtime_role)
                    })
            };
            if let Some(Err(blocker)) = runtime_role_target_result.as_ref() {
                return (
                    None,
                    None,
                    Some(format!("typed TeamFlow runtime role is blocked: {blocker}")),
                    false,
                    vec![blocker.clone()],
                );
            }
            let mut effective_current_target = current_index
                .map(|_| current_node.node_id.clone());
            let mut current_index = current_index;
            if current_index.is_none() {
                if let Some(Ok(target)) = runtime_role_target_result.as_ref() {
                    let runtime_node = match strict_team_flow_node_for_role_selection(
                        role_selection,
                        target,
                    ) {
                        Ok(node) => node,
                        Err(blocker) => {
                            return (
                                None,
                                None,
                                Some(format!("typed TeamFlow runtime role is blocked: {blocker}")),
                                false,
                                vec![blocker],
                            )
                        }
                    };
                    effective_current_target = Some(runtime_node.node_id.clone());
                    current_index = typed_execution_lane_sequence_index_for_target(
                        role_selection,
                        &allowed_next_lane_sequence,
                        &runtime_node.node_id,
                        receipt.downstream_dispatch_last_target.as_deref(),
                    )
                    .map_err(|blocker| {
                        format!("typed TeamFlow runtime role is blocked: {blocker}")
                    })
                    .ok()
                    .flatten();
                }
            }
            let Some(current_index) = current_index else {
                return (None, None, None, false, Vec::new());
            };
            let next_target = allowed_next_lane_sequence.get(current_index + 1);
            if let Some(next_target) = next_target {
                let next_target_resolution = match strict_team_flow_node_for_role_selection(
                    role_selection,
                    next_target,
                ) {
                    Ok(resolution) => resolution,
                    Err(blocker) => {
                    return (
                        None,
                        None,
                        Some(format!(
                            "next typed TeamFlow lane `{next_target}` is blocked: {blocker}"
                        )),
                        false,
                        vec![blocker],
                    )
                    }
                };
                if receipt.downstream_dispatch_target.is_none()
                    && strict_team_flow_node_for_role_selection(role_selection, next_target)
                        .ok()
                        .is_some_and(|lane| lane.stage == "design_gate")
                {
                    let has_specification_evidence = dispatch_receipt_has_execution_evidence(receipt)
                        || tracked_specification_gate_completion_ready(store, role_selection, receipt)
                            .await;
                    let taskflow_feature_ready =
                        spec_first_work_pool_handoff_feature_from_taskflow(store, receipt).await;
                    let spec_task_closed = taskflow_feature_ready.is_some()
                        || (tracked_specification_gate_required(role_selection)
                            && tracked_specification_task_closed(store, role_selection, receipt)
                                .await);
                    let design_doc_finalized = taskflow_feature_ready.is_some()
                        || (tracked_specification_gate_required(role_selection)
                            && tracked_design_doc_finalized(role_selection));
                    let evidence_blocker = effective_current_target
                        .as_deref()
                        .and_then(|target| {
                            strict_team_flow_node_for_role_selection(role_selection, target).ok()
                        })
                        .map(|lane| lane.completion_blocker.clone())
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| blocker_code_str(BlockerCode::PendingSpecificationEvidence).to_string());
                    return (
                        Some("work-pool-pack".to_string()),
                        json_string(
                            role_selection.execution_plan["tracked_flow_bootstrap"]
                                ["work_pool_task"]
                                .get("ensure_command"),
                        ),
                        Some(
                            "design-gate successor requires explicit downstream intent; preserve tracked work-pool blockers before continuing runtime lane selection"
                                .to_string(),
                        ),
                        has_specification_evidence && spec_task_closed && design_doc_finalized,
                        {
                            let mut blockers = Vec::new();
                            if !has_specification_evidence {
                                blockers.push(evidence_blocker.to_string());
                            }
                            if !design_doc_finalized {
                                blockers.push(
                                    blocker_code_value(BlockerCode::PendingDesignFinalize).expect(
                                        "pending design finalize should stay registry-backed",
                                    ),
                                );
                            }
                            if !spec_task_closed {
                                blockers.push(
                                    blocker_code_value(BlockerCode::PendingSpecTaskClose).expect(
                                        "pending spec task close should stay registry-backed",
                                    ),
                                );
                            }
                            blockers
                        },
                    );
                }
                let blocker = effective_current_target
                    .as_deref()
                    .and_then(|target| {
                        strict_team_flow_node_for_role_selection(role_selection, target).ok()
                    })
                    .map(|lane| lane.completion_blocker)
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or_else(|| blocker_code_str(BlockerCode::PendingLaneEvidence).to_string())
                    .to_string();
                let has_lane_evidence = dispatch_receipt_has_execution_evidence(receipt)
                    || dispatch_receipt_allows_synthetic_lane_completion(receipt)
                    || tracked_implementer_task_closed(store, role_selection, receipt).await;
                let missing_owned_scope = request_missing_owned_write_scope_for_dispatch_target(
                    store,
                    role_selection,
                    receipt,
                    &next_target_resolution.dispatch_target,
                )
                .await;
                let command = typed_team_flow_command_for_dispatch_target(
                    role_selection,
                    &next_target_resolution.node_id,
                );
                (
                    Some(next_target_resolution.dispatch_target.clone()),
                    command,
                    Some(format!(
                        "after `{}` evidence is recorded, activate `{}` for the next bounded lane",
                        receipt.dispatch_target, next_target_resolution.dispatch_target
                    )),
                    has_lane_evidence && !missing_owned_scope,
                    {
                        let mut blockers = Vec::new();
                        if !has_lane_evidence {
                            blockers.extend(
                                downstream_preview_blockers_for_missing_lane_evidence(
                                    receipt,
                                    &blocker,
                                ),
                            );
                        }
                        if missing_owned_scope {
                            blockers.push(missing_owned_write_scope_blocker());
                        }
                        blockers
                    },
                )
            } else {
                let blocker = effective_current_target
                    .as_deref()
                    .and_then(|target| {
                        strict_team_flow_node_for_role_selection(role_selection, target).ok()
                    })
                    .map(|lane| lane.completion_blocker.clone())
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or_else(|| blocker_code_str(BlockerCode::PendingLaneEvidence).to_string());
                let has_lane_evidence = dispatch_receipt_has_execution_evidence(receipt)
                    || dispatch_receipt_allows_synthetic_lane_completion(receipt)
                    || tracked_implementer_task_closed(store, role_selection, receipt).await;
                (
                    Some("closure".to_string()),
                    None,
                    Some(
                        "no additional downstream lane is required by the current execution plan after this handoff"
                            .to_string(),
                    ),
                    has_lane_evidence,
                    if has_lane_evidence {
                        Vec::new()
                    } else {
                        downstream_preview_blockers_for_missing_lane_evidence(receipt, &blocker)
                    },
                )
            }
        }
        _ => (None, None, None, false, Vec::new()),
    }
}

#[cfg(test)]
fn lawful_explicit_downstream_dispatch_target(
    execution_plan: &serde_json::Value,
    allowed_next_lane_sequence: &[String],
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    explicit_target: &str,
) -> Option<RuntimeDispatchTargetResolution> {
    lawful_explicit_downstream_dispatch_target_for_sequence(
        execution_plan,
        allowed_next_lane_sequence,
        &receipt.dispatch_target,
        receipt.downstream_dispatch_last_target.as_deref(),
        explicit_target,
    )
}

#[cfg(test)]
fn lawful_explicit_downstream_dispatch_target_for_sequence(
    execution_plan: &serde_json::Value,
    allowed_next_lane_sequence: &[String],
    completed_dispatch_target: &str,
    previous_dispatch_target: Option<&str>,
    explicit_target: &str,
) -> Option<RuntimeDispatchTargetResolution> {
    let target_resolution =
        diagnostic_resolve_runtime_dispatch_target(execution_plan, explicit_target)?;
    let normalized_sequence = allowed_next_lane_sequence
        .iter()
        .map(|candidate| {
            diagnostic_resolve_runtime_dispatch_target(execution_plan, candidate)
                .map(|resolution| canonical_dispatch_target_name(&resolution.dispatch_target))
        })
        .collect::<Option<Vec<_>>>()?;
    let normalized_current_target =
        diagnostic_resolve_runtime_dispatch_target(execution_plan, completed_dispatch_target)
            .map(|resolution| canonical_dispatch_target_name(&resolution.dispatch_target))?;
    let normalized_previous_target = previous_dispatch_target.and_then(|previous_target| {
        diagnostic_resolve_runtime_dispatch_target(execution_plan, previous_target)
            .map(|resolution| canonical_dispatch_target_name(&resolution.dispatch_target))
    });
    let current_index = execution_lane_sequence_index_for_target(
        &normalized_sequence,
        &normalized_current_target,
        normalized_previous_target.as_deref(),
    )?;
    let next_target = normalized_sequence.get(current_index + 1)?;
    (next_target == &canonical_dispatch_target_name(&target_resolution.dispatch_target))
        .then_some(target_resolution)
}

#[cfg(test)]
fn lawful_explicit_rework_downstream_dispatch_target(
    execution_plan: &serde_json::Value,
    receipt: &crate::state_store::RunGraphDispatchReceipt,
    explicit_target: &str,
) -> Option<RuntimeDispatchTargetResolution> {
    let route = crate::runtime_dispatch_result_evidence::authorized_dispatch_rework_route_from_receipt_fields(
        receipt.downstream_dispatch_result_path.as_deref(),
        receipt.dispatch_result_path.as_deref(),
        receipt.dispatch_packet_path.as_deref(),
        &receipt.dispatch_target,
    )?;
    let explicit_target = normalized_dispatch_target_token(explicit_target);
    if explicit_target.is_empty()
        || normalized_dispatch_target_token(&route.allowed_next_node) != explicit_target
    {
        return None;
    }
    diagnostic_resolve_runtime_dispatch_target(execution_plan, &route.allowed_next_node)
}

